        // una alternativa la agrega por el MISMO camino del escaneo (elegirPresentacion).
        const altSheet = ref(null);
        const cerrarAltSheet = () => { altSheet.value = null; };
        // [2.8.261 FIX] Lookup por clave normalizada (ver stockMapZ). Lo usan el sheet de
        // Parecidos, tieneAlternativas y el "N disp." del sheet de Presentaciones.
        const _stockDeCod = (cod) => {
            const v = stockMapZ.value[_znk(cod) + '_' + _znk(config.value.zona || '')];
            return v === undefined ? null : v;
        };
        const abrirAlternativas = (base) => {
            try { playBeepOK && playBeepOK(); } catch(_){}
            try { navigator.vibrate && navigator.vibrate(12); } catch(_){}
            try {
                const sku = String(base.sku || '').trim();
                const items = [];
                (db.value.PRESENTACIONES || []).forEach(p => {
                    if (String(p.SKU_Base).trim() !== sku) return;
                    const st = _stockDeCod(p.Cod_Barras);
                    if (st !== null && st > 0) items.push({ cod: String(p.Cod_Barras), nombre: p.Empaque, precio: +p.Precio_Venta || 0, stock: st, tipo: 'familia' });
                });
                const conSust = (db.value.PRESENTACIONES || []).find(p => String(p.SKU_Base).trim() === sku && Array.isArray(p.Sustitutos) && p.Sustitutos.length);
                (conSust ? conSust.Sustitutos : []).forEach(s => {
                    const st = _stockDeCod(s.cod);
                    if (st === null || st <= 0) return;
                    const pr = (db.value.PRESENTACIONES || []).find(p => String(p.Cod_Barras).trim() === String(s.cod).trim());
                    items.push({ cod: String(s.cod), nombre: s.nombre, precio: pr ? (+pr.Precio_Venta || 0) : 0, stock: st, tipo: 'sustituto', motivo: s.motivo || '' });
                });
                // [2.8.260 FIX] Antes: `if (!items.length) return;` → el botón 🔄 PARECIDOS
                // parecía muerto cuando nada de la familia ni los sustitutos tenía stock.
                // Ahora el sheet SIEMPRE abre; con 0 items muestra su estado vacío.
                altSheet.value = { para: base.nombreCorto || base.nombre || '', items: items.slice(0, 8), vacio: !items.length };
            } catch (e) { /* nunca romper la venta por una sugerencia */ }
        };
        // [2.8.260] ¿este producto tiene AL MENOS UNA alternativa con stock en mi zona?
        // El botón 🔄 PARECIDOS solo debe palpitar si de verdad hay algo que ofrecer.
        // PERF: el binding corre por cada card en CADA re-render (miles) → la búsqueda
        // cruda NO puede vivir en el :class. Memo por SKU; el cache se limpia solo cuando
        // cambia el stock de la zona o el catálogo (watch de abajo).
        const _altCache = new Map();
        const tieneAlternativas = (prod) => {
            const sku = String((prod && prod.sku) || '').trim();
            if (!sku) return false;
            if (_altCache.has(sku)) return _altCache.get(sku);
            let hay = false;
            try {
                const PR = db.value.PRESENTACIONES || [];
                for (let i = 0; i < PR.length; i++) {
                    const p = PR[i];
                    if (String(p.SKU_Base).trim() !== sku) continue;
                    const st = _stockDeCod(p.Cod_Barras);
                    if (st !== null && st > 0) { hay = true; break; }
                }
                if (!hay) {
                    const conSust = PR.find(p => String(p.SKU_Base).trim() === sku && Array.isArray(p.Sustitutos) && p.Sustitutos.length);
                    if (conSust) hay = conSust.Sustitutos.some(x => { const st = _stockDeCod(x.cod); return st !== null && st > 0; });
                }
            } catch(_) { hay = false; }
            _altCache.set(sku, hay);
            return hay;
        };
        // El stock de zona y el catálogo son las Únicas entradas del cálculo → al cambiar
        // cualquiera, el memo se tira entero (barato: se rellena perezosamente al render).
        watch([stockMapZ, db], () => { _altCache.clear(); });
        // [diag 2.8.263] visible en consola del vendedor: ¿el payload trae Sustitutos y cuántos palpitan?
        watch(db, () => { setTimeout(() => { try {
            const PR = db.value.PRESENTACIONES || [];
            const conS = PR.filter(p => Array.isArray(p.Sustitutos) && p.Sustitutos.length).length;
            let palp = 0; const vistos = new Set();
            PR.forEach(p => { const sku = String(p.SKU_Base).trim();
                if (vistos.has(sku)) return; vistos.add(sku);
                const st = _stockDeCod(p.Cod_Barras);
                if (st !== null && st <= 0 && tieneAlternativas({ sku })) palp++; });
            console.log('[sustitutos] vendibles con Sustitutos:', conS, '· productos que palpitan en tu zona:', palp, '· zona=', config.value.zona);
        } catch(_){} }, 1500); });
        const elegirAlternativa = (it) => {
            cerrarAltSheet();
            const pres = (db.value.PRESENTACIONES || []).find(p => String(p.Cod_Barras).trim().toUpperCase() === String(it.cod).trim().toUpperCase());
            if (!pres) return;
            const base = productosCatalogo.value.find(p => String(p.sku).trim() === String(pres.SKU_Base).trim());
            if (!base) return;
            elegirPresentacion(base, pres);
        };
        const showScanPreview = (prod, label, kind, extra) => {
            const id = Date.now();
            scanPreview.value = {
                id,
                nombre: prod.nombreCorto || prod.nombre || 'Producto',
                precio: (prod.precio !== undefined ? prod.precio : prod.precioUnitario || 0).toFixed(2),
                imagen: prod.imagen || '',
                label:  label || 'PRODUCTO',
                kind:   kind  || 'ok',
                extra:  extra || ''
            };
            setTimeout(() => {
                if (scanPreview.value && scanPreview.value.id === id) scanPreview.value = null;
            }, 1250);
        };

        // ── Estado "esperando Enter / escaneando" + detector de origen scanner vs tipeo ───
        // Idea: un scanner físico/cámara mete los chars en <30ms cada uno; tipear toma 100ms+.
        // Si fue scanner -> match SOLO exacto (no parcial). Si fue tipeo -> permite búsqueda parcial.
        const scanningPending = ref(false);
        let _scanIdleTimer = null;
        let _firstInputTime = 0;
        let _lastWasFastInput = false;
        const onScanInput = () => {
            filtrarCatalogoDebounced();
            scanningPending.value = false;
            const now = Date.now();
            const len = (bBuscador.value || '').length;
            if (len === 0) {
                _firstInputTime = 0;
                _lastWasFastInput = false;
            } else if (_firstInputTime === 0) {
                _firstInputTime = now;
            } else if (len >= 4) {
                const elapsed = now - _firstInputTime;
                // Promedio ≤ 25ms por char => imposible humano => scanner / pegado
                if (elapsed < (len * 25)) _lastWasFastInput = true;
            }
            if (_scanIdleTimer) clearTimeout(_scanIdleTimer);
            if (len > 0) {
                _scanIdleTimer = setTimeout(() => { scanningPending.value = true; }, 250);
            }
        };

        // ╔══════════════════════════════════════════════════════════════
        // ║  WELCOME OVERLAY — pantalla motivacional al arrancar turno
        // ╚══════════════════════════════════════════════════════════════
        const _frasesMotivacion = [
            'Cada cliente que entra es una historia esperando ser escuchada por ti.',
            'Tu sonrisa cambia el día de alguien hoy.',
            'El mejor vendedor no vende — ayuda a comprar.',
            'Hoy alguien va a salir feliz porque tú estuviste ahí.',
            'Los clientes difíciles son tus mejores maestros.',
            'Vender es resolver problemas a personas reales.',
            'El cliente no compra el producto, te compra a ti.',
            'Cada NO te acerca al SÍ.',
            'Tu actitud hoy define el día de muchas personas.',
            'Eres el primer rostro de la tienda — y qué rostro.',
            'No vendes cosas, ofreces soluciones.',
            'Tu paciencia hoy es el éxito de mañana.',
            'Detrás de cada venta hay alguien que necesitaba algo. Tú lo entregaste.',
            'Hoy puedes ser la mejor parte del día de alguien.',
            'Vender no es convencer, es conectar.',
            'Tu energía vende más que cualquier descuento.',
            'Ser cajero es ser embajador. Hoy representas a Inversiones MOS.',
            'El cliente difícil es el que más te recuerda. Tú decides cómo.',
            'Cada turno es una oportunidad de ser mejor que ayer.',
            'No es solo una venta. Es confianza ganada.',
            'Hoy alguien va a entrar nervioso y salir tranquilo gracias a ti.',
            'La paciencia es la herramienta más poderosa del cajero.',
            'Pequeños gestos generan grandes recuerdos.',
            'Hoy vas a sorprender a alguien con tu atención.'
        ];

        const welcomeOverlay = ref({
            visible: false, fading: false,
            nombre: '', iniciales: '', rol: '', saludo: '', emoji: '',
            tag: null,
            quote: '', quoteShown: '', typing: false,
            streak: 0, streakShown: 0,
            session: 0, sessionShown: 0,
            ventasHoy: 0, ventasShown: '0.00',
            confetti: [], sparkles: []
        });

        // ╔══════════════════════════════════════════════════════════════
        // ║  WAKE LOCK + SALVAPANTALLA por inactividad
        // ╚══════════════════════════════════════════════════════════════
        const idleScreen = ref({
            visible: false, fading: false,
            hora: '00:00', seg: '00',
            cajero: '', zona: '',
            quote: '', quoteFading: false,
            tickets: 0, totalHoy: '0.00',
            totalZona: '0.00',
            meta: '0.00', metaPct: 0, metaFalta: '0.00', metaSuperada: false,
            metaTiene: false,      // [754] la zona TIENE meta configurada (política 729: sin default)
            verMonto: false,       // [754] privacidad: vendedor solo barra; cajero/admin barra + montos
            wakeLockActivo: false,
            particles: []
        });

        // Wake lock y salvapantalla: SIEMPRE activos por política — el cajero no
        // puede desactivarlos. Tiempo del salvapantalla fijo en 2 min.
        // Meta diaria fija (no editable por el cajero — la define el supervisor).
        const idleConfig = ref({
            wakeLockEnabled: true,
            saverEnabled:    true,
            saverMinutos:    2
            // [754] metaDiaria eliminada: leía la clave global muerta evalMetaCajero con
            // default 1000 inventado. La meta real es la política de la ZONA (729/730)
            // y llega por me.meta_progreso_zona (ver _refrescarMetaZona).
        });

        let _wakeLockSentinel = null;
        let _idleTimer = null;
        let _idleClockInterval = null;
        let _idleQuoteInterval = null;

        // ── Wake Lock ────────────────────────────────────────
        const _activarWakeLock = async () => {
            if (!idleConfig.value.wakeLockEnabled) return;
            if (!('wakeLock' in navigator)) return;
            if (_wakeLockSentinel) return; // ya activo
            try {
                _wakeLockSentinel = await navigator.wakeLock.request('screen');
                idleScreen.value.wakeLockActivo = true;
                _wakeLockSentinel.addEventListener('release', () => {
                    _wakeLockSentinel = null;
                    idleScreen.value.wakeLockActivo = false;
                });
            } catch(e) { /* dispositivo no soporta o tab en background */ }
        };
        const _liberarWakeLock = async () => {
            if (_wakeLockSentinel) {
                try { await _wakeLockSentinel.release(); } catch(e) {}
                _wakeLockSentinel = null;
                idleScreen.value.wakeLockActivo = false;
            }
        };

        // Re-activar wake lock cuando la app vuelve al foreground
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible' && config.value.completado) {
                _activarWakeLock();
                // Al volver a primer plano, chequear si el catálogo cambió mientras estuvo en
                // background (el poller no corre oculto). Money-safe: _chequearVersionCatalogo
                // difiere si hay venta en curso.
                _chequearVersionCatalogo();
                // [perf sesión larga + money-safe · rev 500x] Al volver a primer plano:
                // 1º DRENAR la cola de mutaciones de DINERO — refresca `_mutPend` sincrónicamente para que el
                //    merge NO revierta en pantalla un cobro/anulación en vuelo (evita que el cajero re-cobre).
                // 2º refrescar ventas/cobros (los pollers se pausan con la pestaña oculta).
                try { _reintentarMutacionesDinero(); } catch (_) {}
                try { actualizarVentasZonaSilencioso(); } catch (_) {}
                try { if (typeof cargarCobrosAsignados === 'function') cargarCobrosAsignados(); } catch (_) {}
            }
        });
        // Volver foco a la ventana (sin pasar por hidden, p.ej. cambio de pestaña a misma app)
        window.addEventListener('focus', () => { _chequearVersionCatalogo(); });

        // ── Detector de inactividad ──────────────────────────
        const _resetIdleTimer = () => {
            if (idleScreen.value.visible) ocultarSalvapantalla();
            if (_idleTimer) clearTimeout(_idleTimer);
            if (!idleConfig.value.saverEnabled) return;
            if (!config.value.completado) return;
            const ms = (parseInt(idleConfig.value.saverMinutos, 10) || 2) * 60 * 1000;
            _idleTimer = setTimeout(mostrarSalvapantalla, ms);
        };

        // ── [754] Meta del salvapantallas = política de la ZONA (729/730, vigencia por día,
        //    SIN default) vía me.meta_progreso_zona. Cache local para modo offline. Mientras
        //    la salva está visible se refresca cada 60s (antes quedaba congelada).
        let _idleMetaInterval = null;
        let _idleStatsRefrescar = null;   // [755b] recalc de stats personales, seteado por la salva
        const _aplicarMetaZona = (d) => {
            if (!d) return;
            const pct = parseFloat(d.pct) || 0;
            idleScreen.value.metaTiene    = !!d.tieneMeta;
            idleScreen.value.meta         = (parseFloat(d.metaDiaria) || 0).toFixed(2);
            idleScreen.value.totalZona    = (parseFloat(d.lleva) || 0).toFixed(2);
            idleScreen.value.metaFalta    = (parseFloat(d.faltan) || 0).toFixed(2);
            idleScreen.value.metaPct      = Math.min(200, pct);
            idleScreen.value.metaSuperada = pct >= 100;
        };
        const _refrescarMetaZona = async () => {
            const zona = String(config.value.zona || '').trim();
            if (!zona) { idleScreen.value.metaTiene = false; return; }
            try {
                const _tk = await _mintTokenSB();
                if (!_tk) throw new Error('sin token');
                const r = await _meFetchTimeout(`${SUPABASE_URL}/rest/v1/rpc/meta_progreso_zona`, {
                    method: 'POST',
                    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + _tk, 'Content-Profile': 'me', 'Content-Type': 'application/json' },
                    body: JSON.stringify({ p: { zona } })
                }, 8000);
                const j = await r.json().catch(() => null);
                if (j && j.ok && j.data) {
                    _aplicarMetaZona(j.data);
                    localStorage.setItem('mosexpress_meta_zona_cache', JSON.stringify(j.data));
                    return;
                }
                throw new Error((j && j.error) || 'sin data');
            } catch (_) {
                // Offline / fallo → último dato bueno conocido (si existe)
                try { _aplicarMetaZona(JSON.parse(localStorage.getItem('mosexpress_meta_zona_cache') || 'null')); } catch (__) {}
            }
        };

        // ── Mostrar salvapantalla ────────────────────────────
        const mostrarSalvapantalla = () => {
            // No interrumpir tareas críticas — pero RE-ARMAR el timer: antes un guard
            // (p.ej. modal de pago abierto justo al vencer) mataba la salva hasta la
            // próxima actividad del usuario.
            // `modoCajero`: la estación de cobro NO se tapa nunca. Taparla es exactamente el
            // modo reposo que quedó descartado — y deja al cajero mirando un reloj con un
            // cliente enfrente.
            if (modalPago.value || camaraAbierta.value || welcomeOverlay.value.visible || !config.value.completado || modoCajero.value) {
                if (_idleTimer) clearTimeout(_idleTimer);
                _idleTimer = setTimeout(mostrarSalvapantalla, 60 * 1000);
                return;
            }

            // Inicializar datos
            const _now = new Date();
            const _hh = String(_now.getHours()).padStart(2, '0');
            const _mm = String(_now.getMinutes()).padStart(2, '0');
            const _ss = String(_now.getSeconds()).padStart(2, '0');

            // Dos cálculos distintos:
            //   1) PERSONAL (tickets + total propio del usuario): ventasHoy o filtrado por vendedor
            //   2) ZONA (progreso hacia meta — colectivo): SUMA de toda ventasZona,
            //      sin filtro de vendedor. La meta diaria es de la zona, no individual.
            // Solo cuenta EFE/VIRTUAL/MIXTO en ambos casos (no POR_COBRAR / CREDITO / ANULADO).
            const _startTs = sessionStartTime.value ? new Date(sessionStartTime.value).getTime() : 0;
            const _miNombre = String(config.value.vendedor || '').trim().toUpperCase();
            const _esConDinero = (m) => m && m !== 'ANULADO' && m !== 'POR_COBRAR' && m !== 'CREDITO';

            // 1. STATS PERSONALES (lo que TÚ has hecho en tu sesión)
            // [755b] extraído a función para refrescarse EN VIVO cada 60s junto con la meta
            // (antes una salva de 30 min mostraba tus ventas de hace 30 min).
            const _statsPersonalesIdle = () => {
                const _fuentePers = config.value.esCajero
                    ? (ventasZona.value && ventasZona.value.length ? ventasZona.value : (ventasHoy.value || []))
                    : (ventasHoy.value || []);
                let _ticks = 0, _total = 0;
                _fuentePers.forEach(v => {
                    if ((v.timestamp || 0) < _startTs) return;
                    if (v.anulada) return;
                    const vendV = String(v.raw_data?.auth?.vendedor || '').trim().toUpperCase();
                    if (_miNombre && vendV && vendV !== _miNombre) return;
                    const m = String(v.cobradoMetodo || v.raw_data?.header?.metodo || '').toUpperCase().trim();
                    if (!_esConDinero(m)) return;
                    _ticks++;
                    _total = _money(_total + (parseFloat(v.total) || 0));
                });
                idleScreen.value.tickets  = _ticks;
                idleScreen.value.totalHoy = _total.toFixed(2);
            };
            _idleStatsRefrescar = _statsPersonalesIdle;   // el tick de 60s la reusa
            _statsPersonalesIdle();

            // 2. [754] META DE ZONA: ya no se calcula acá (el cálculo local mentía — para el
            // vendedor "la zona" era su propio total, y para el cajero era solo su caja).
            // Viene del server (me.meta_progreso_zona = todas las cajas de la zona, hoy Lima):
            // primero el último dato cacheado (pintado instantáneo) y enseguida el fresco.
            try { _aplicarMetaZona(JSON.parse(localStorage.getItem('mosexpress_meta_zona_cache') || 'null')); } catch (_) {}
            _refrescarMetaZona();
            // Privacidad: vendedor SOLO barra; cajero/admin/master barra + montos.
            const _rolIdle = String(config.value.rol || '').toUpperCase();
            const _verMonto = !!config.value.esCajero || _rolIdle === 'ADMIN' || _rolIdle === 'MASTER';

            // Frase aleatoria
            const _q = _frasesMotivacion[Math.floor(Math.random() * _frasesMotivacion.length)];

            // Partículas (8 sutiles)
            const _parts = [];
            for (let i = 0; i < 8; i++) {
                _parts.push({
                    id: i,
                    left: Math.random() * 100,
                    dx: (Math.random() - 0.5) * 100,
                    delay: Math.random() * 18,
                    duration: 14 + Math.random() * 8
                });
            }

            idleScreen.value = {
                ...idleScreen.value,
                visible: true, fading: false,
                hora: _hh + ':' + _mm,
                seg: _ss,
                cajero: (config.value.vendedor || '') + (config.value.esCajero ? ' · Cajero' : ' · Vendedor'),
                zona: config.value.zona || config.value.estacion?.Estacion_Nombre || '',
                quote: _q, quoteFading: false,
                // [755b] tickets/totalHoy los setea _statsPersonalesIdle (ya corrió arriba y refresca cada 60s)
                verMonto: _verMonto,   // [754] los campos de meta los setea _aplicarMetaZona
                particles: _parts
            };

            // Actualizar reloj cada segundo
            if (_idleClockInterval) clearInterval(_idleClockInterval);
            _idleClockInterval = setInterval(() => {
                const n = new Date();
                idleScreen.value.hora = String(n.getHours()).padStart(2, '0') + ':' + String(n.getMinutes()).padStart(2, '0');
                idleScreen.value.seg  = String(n.getSeconds()).padStart(2, '0');
            }, 1000);

            // Rotar frase cada 8s con fade
            if (_idleQuoteInterval) clearInterval(_idleQuoteInterval);
            _idleQuoteInterval = setInterval(() => {
                idleScreen.value.quoteFading = true;
                setTimeout(() => {
                    idleScreen.value.quote = _frasesMotivacion[Math.floor(Math.random() * _frasesMotivacion.length)];
                    idleScreen.value.quoteFading = false;
                }, 500);
            }, 8000);

            // [754] Meta EN VIVO mientras la salva está visible (antes quedaba congelada:
            // una salva de 30 min mostraba números de hace 30 min).
            if (_idleMetaInterval) clearInterval(_idleMetaInterval);
            _idleMetaInterval = setInterval(() => {
                _refrescarMetaZona();
                if (_idleStatsRefrescar) { try { _idleStatsRefrescar(); } catch (_) {} }   // [755b] 🛒/💰 en vivo
            }, 60000);
        };

        // ── Ocultar salvapantalla ────────────────────────────
        // [v2.5.30] Al salir del salvapantallas SIEMPRE volver a POS con
        // foco en scanner. Patrón "all roads lead to POS" — el flujo natural
        // de la tienda es vender, no administrar. Si no hay caja abierta y
        // es cajero, queda donde estaba (POS module igual visible).
        const ocultarSalvapantalla = (opts) => {
            opts = opts || {};
            if (!idleScreen.value.visible || idleScreen.value.fading) {
                // Por si llaman cuando ya está oculto (fast-path)
                if (opts.forceFocus && scannerInput.value) {
                    try { scannerInput.value.focus({ preventScroll: true }); } catch(_){}
                }
                return;
            }
            idleScreen.value.fading = true;
            if (_idleClockInterval) { clearInterval(_idleClockInterval); _idleClockInterval = null; }
            if (_idleQuoteInterval) { clearInterval(_idleQuoteInterval); _idleQuoteInterval = null; }
            if (_idleMetaInterval)  { clearInterval(_idleMetaInterval);  _idleMetaInterval  = null; }   // [754]
            setTimeout(() => {
                idleScreen.value.visible = false;
                idleScreen.value.fading = false;
                // [v2.5.30] Volver a POS + foco scanner
                if (config.value.completado) {
                    currentModule.value = 'POS';
                    nextTick(() => {
                        if (scannerInput.value) {
                            try { scannerInput.value.focus({ preventScroll: true }); } catch(_){}
                        }
                    });
                }
                _resetIdleTimer(); // arrancar countdown de nuevo
            }, opts.forceFocus ? 50 : 380); // fast unmount si vino de scan
        };

        // [v2.5.30] Listener global de teclas durante salvapantallas.
        // Si el scanner físico envía dígitos + Enter mientras está la pantalla
        // de inactividad, capturamos el código → ocultamos salvapantallas
        // rápido → cambiamos a POS → inyectamos código → procesamos como scan.
        // Patrón scanner USB típico: ráfaga de dígitos en <200ms + Enter.
        let _idleScanBuffer = '';
        let _idleScanTimer = null;
        const _onIdleKeydown = (e) => {
            // Solo activo cuando salvapantallas está visible
            if (!idleScreen.value.visible) return;
            // Ignorar si hay modales bloqueantes (poco probable bajo salva)
            if (!config.value.completado) return;
            // [modo cajero] antes solo dígitos: un correlativo (NVM2-000531) o la cadena de
            // SUNAT de una boleta no despertaban la pantalla, y son justo lo que escanea el
            // cajero. Mismo charset que el captor de ráfaga.
            const _ich = (e.code === 'Minus' || e.code === 'NumpadSubtract') ? '-' : e.key;
            // el QR de SUNAT trae espacios alrededor de cada "|": sin aceptarlos el buffer se
            // reseteaba a mitad de la cadena. La ráfaga sigue siendo el filtro contra el tecleo.
            if (/^[0-9A-Za-z\-|./ ]$/.test(_ich)) {
                _idleScanBuffer += _ich;
                if (_idleScanTimer) clearTimeout(_idleScanTimer);
                // Si pasa más de 400ms entre teclas, considerar que NO es scanner sino teclado humano
                _idleScanTimer = setTimeout(() => { _idleScanBuffer = ''; }, 400);
                return;
            }
            // Enter con buffer mínimo de 4 dígitos → procesar como scan
            if (e.key === 'Enter' && _idleScanBuffer.length >= 4) {   // ráfaga completa
                const codigo = _idleScanBuffer;
                _idleScanBuffer = '';
                if (_idleScanTimer) { clearTimeout(_idleScanTimer); _idleScanTimer = null; }
                // [v2.8.30] Ocultar salvapantallas + RUTEAR POR CONTEXTO (no forzar POS a ciegas).
                // Si había un flujo de guía abierto debajo del salvapantallas, el código va a la
                // GUÍA, no al carrito de venta. Sin flujo de guía → va a venta.
                ocultarSalvapantalla({ forceFocus: !_enFlujoGuia() });
                _despacharScanContexto(codigo);
                return;
            }
            // Otra tecla no-dígito → resetear buffer
            if (e.key !== 'Enter') {
                _idleScanBuffer = '';
                if (_idleScanTimer) { clearTimeout(_idleScanTimer); _idleScanTimer = null; }
            }
        };
        window.addEventListener('keydown', _onIdleKeydown);

        // ════════════════════════════════════════════════════════════════════════════
        // [v2.8.30] CAPTOR GLOBAL DEL SCANNER FÍSICO EN FLUJO DE GUÍA (anti-cruce con venta)
        // ════════════════════════════════════════════════════════════════════════════
        // Cuando hay un flujo de guía/recepción/auditoría ABIERTO y el scanner USB dispara
        // una ráfaga de dígitos+Enter, pero el FOCO se perdió (un toast/botón/blur lo robó),
        // el Enter caería en el buscador del POS y el producto entraría al CARRITO DE VENTA.
        // Este captor detecta la ráfaga rápida (paso scanner) y la rutea a la GUÍA por
        // contexto. Es CONSERVADOR: NO actúa si el foco YA está en el input correcto del
        // contexto (deja que el @keyup.enter normal trabaje), ni si el foco está en un
        // <input>/<textarea> distinto donde el operario está escribiendo cantidades/notas.
        let _hwGuiaBuffer = '';
        let _hwGuiaT0 = 0;
        let _hwGuiaTimer = null;
        const _CTX_INPUT_DOM = { guiaBusq: 'guiaBusq', rwBusq: 'rwBusq', rwIdGuia: 'rwIdGuia', auditBusq: 'auditBusq' };
        const _onHwGuiaKeydown = (e) => {
            if (modoCajero.value) return;              // la estación de cobro tiene su propio captor
            if (idleScreen.value.visible) return;     // el salvapantallas tiene su propio captor
            if (!_enFlujoGuia()) { _hwGuiaBuffer = ''; return; }  // solo dentro de un flujo de guía
            const ctx = _scanContextActivo();
            const ae = document.activeElement;
            const tag = ae && ae.tagName ? ae.tagName.toUpperCase() : '';
            // Si el foco está en el input CORRECTO del contexto, deja que el handler normal trabaje.
            if (ae && ae.matches && ae.matches('input,textarea')) {
                if (ae.getAttribute && ae.getAttribute('data-ctx-input') === _CTX_INPUT_DOM[ctx.input]) { _hwGuiaBuffer = ''; return; }
                // [v2.8.31] ⚠ Si el foco quedó en el SCANNER DE VENTA mientras hay un flujo de guía
                // abierto (foco mal dirigido: tap accidental, refoco residual), NO dejar que el scan
                // caiga en el carrito de venta — el captor lo rutea a la guía por contexto (más abajo).
                // Cualquier OTRO campo editable (cantidad, nota, peso de granel) sí es tecleo legítimo
                // del operario → no interferir.
                if (ae !== scannerInput.value) return;
                // (cae al buffer de ráfaga: solo se ruteará si es velocidad de scanner, ver abajo)
            }
            const now = Date.now();
            // [fix layout ES-LatAm] e.code (tecla física) para el "-": en teclado Español escribe "'".
            // Además ACEPTAR "-" en el charset (antes solo [0-9A-Za-z] → un código con "-" reseteaba
            // el buffer y jamás se capturaba, ej. WH-9S7XBPX).
            const ch = (e.code === 'Minus' || e.code === 'NumpadSubtract') ? '-' : e.key;
            // [modo cajero] el QR de una boleta o factura trae la cadena de SUNAT, CON espacios:
            // "20610714057 | 01 | FM01 | 000053 | 1.83 | 12.00 | 18/08/2026 | …". Sin aceptar
            // | . / y el espacio, el buffer se reseteaba a mitad de la cadena y el Enter llegaba
            // vacío: los CPE no se podían escanear desde fuera de la estación. La ráfaga
            // (≤35ms/tecla) sigue siendo el filtro contra el tecleo humano.
            if (/^[0-9A-Za-z\-|./ ]$/.test(ch)) {
                if (!_hwGuiaBuffer) _hwGuiaT0 = now;
                _hwGuiaBuffer += ch;
                if (_hwGuiaTimer) clearTimeout(_hwGuiaTimer);
                _hwGuiaTimer = setTimeout(() => { _hwGuiaBuffer = ''; }, 400); // >400ms entre teclas = humano, no scanner
                return;
            }
            if (e.key === 'Enter' && _hwGuiaBuffer.length >= 4) {
                const elapsed = now - _hwGuiaT0;
                const cod = _hwGuiaBuffer;
                _hwGuiaBuffer = '';
                if (_hwGuiaTimer) { clearTimeout(_hwGuiaTimer); _hwGuiaTimer = null; }
                // Ráfaga scanner-paced (≈≤30ms/char) y foco fuera del input correcto → ruteo por contexto.
                if (elapsed < (cod.length * 35)) {
                    e.preventDefault();
                    // [v2.8.31] Si el foco estaba en el SCANNER DE VENTA, los dígitos ya entraron a
                    // bBuscador (v-model) y el @keyup.enter de ese input dispararía procesarEscaneoOBusqueda
                    // DESPUÉS (preventDefault de keydown NO cancela el keyup). Limpiamos el buscador para
                    // que ese keyup haga no-op (procesarEscaneoOBusqueda corta con `if (!code) return`),
                    // evitando que el MISMO scan se procese DOBLE (guía + venta).
                    if (document.activeElement === scannerInput.value) {
                        bBuscador.value = '';
                        scanningPending.value = false;
                    }
                    _despacharScanContexto(cod);
                }
                return;
            }
            if (e.key !== 'Enter') { _hwGuiaBuffer = ''; if (_hwGuiaTimer) { clearTimeout(_hwGuiaTimer); _hwGuiaTimer = null; } }
        };
        window.addEventListener('keydown', _onHwGuiaKeydown, true); // capture: antes que los @keyup de los inputs

        // ════════════════════════════════════════════════════════════════════
        // [Atajos PC · pro-mode] Autodetecta PC (mouse fino + hover) → habilita atajos de teclado.
        //   ESPACIO → Cobrar (POS · carrito>0 · buscador VACÍO)  |  Confirmar+imprimir (modal de pago)
        //   ESC     → cerrar modal de pago  |  limpiar el input de gramos del granel (queda vacío)
        //   /       → ir al buscador        |  Alt+1/2/3 → POS / CAJA / TOOLS
        // GUARD DE ORO: si el cajero está ESCRIBIENDO (buscador con texto, o un campo de nombre) → la tecla
        // pasa normal (no rompe la búsqueda por nombre ni el escaneo). El input de gramos NO cuenta como "texto".
        // ════════════════════════════════════════════════════════════════════
        const esPC = ref(false);
        const cobrarFx = ref(false);   // flash visual del botón Cobrar/Confirmar
        const _fxAtajo = (sonido) => {
            try {
                const ctx = _audioCtx(); if (!ctx) return;
                const o = ctx.createOscillator(), g = ctx.createGain();
                o.connect(g); g.connect(ctx.destination); o.type = 'sine';
                if (sonido === 'print') { o.frequency.setValueAtTime(440, ctx.currentTime); o.frequency.exponentialRampToValueAtTime(210, ctx.currentTime + 0.13); }
                else { o.frequency.setValueAtTime(680, ctx.currentTime); o.frequency.exponentialRampToValueAtTime(1020, ctx.currentTime + 0.12); }
                g.gain.setValueAtTime(0.22, ctx.currentTime); g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.16);
                o.start(); o.stop(ctx.currentTime + 0.17);
            } catch(_){}
            try { if (navigator.vibrate) navigator.vibrate(40); } catch(_){}
            cobrarFx.value = true; setTimeout(() => { cobrarFx.value = false; }, 460);
        };
        let _atajoHintMostrado = false;
        const _atajosPC = (e) => {
            if (!esPC.value || !config.value.completado) return;
            const ae = document.activeElement;
            const aeEsScanner = (ae === scannerInput.value);   // el scanner ES texto pero con buscador vacío = "listo para cobrar"
            const enTexto = !!(ae && (ae.tagName === 'TEXTAREA' ||
                (ae.tagName === 'INPUT' && !['number','checkbox','radio','range'].includes(String(ae.type||'').toLowerCase()) && !ae.classList.contains('gramos-input'))));

            if (e.key === 'Escape') {
                // En el granel: limpiar el campo (queda vacío para tipear de cero)
                if (ae && ae.classList && ae.classList.contains('gramos-input')) {
                    const wrap = ae.closest('[data-cart-idx]');
                    const idx = wrap ? parseInt(wrap.getAttribute('data-cart-idx'), 10) : -1;
                    if (idx >= 0 && carrito.value[idx]) carrito.value[idx]._gramosStr = '';
                    e.preventDefault();
                    return;
                }
                if (modalPago.value) { modalPago.value = false; try { _prereservaCancelar(); } catch(_){} e.preventDefault(); return; }
                return;
            }
            if (e.key === ' ') {
                // [Lote1-C · fix A2] Espacio SOSTENIDO no repite el atajo (doble venta).
                // En campos de texto reales se respeta el repeat nativo (escribir espacios).
                if (e.repeat) { if (!enTexto || aeEsScanner) e.preventDefault(); return; }
                if (modalPago.value) {
                    // si está escribiendo un nombre (campo de texto que NO es el scanner) → dejar el espacio
                    if (enTexto && !aeEsScanner) return;
                    const b = document.querySelector('[data-pago-confirmar]');
                    if (b && !b.disabled) { e.preventDefault(); b.click(); _fxAtajo('print'); }
                    return;
                }
                // Cobrar: POS · carrito>0 · buscador VACÍO · (foco en el scanner vacío  o  fuera de un campo de texto)
                if (currentModule.value === 'POS' && carrito.value.length > 0 && String(bBuscador.value || '').trim() === '' && (aeEsScanner || !enTexto)) {
                    e.preventDefault();
                    abrirModalPago(); _fxAtajo('cobrar');
                    if (!_atajoHintMostrado) { _atajoHintMostrado = true; agregarToast('Atajo ⎵', 'Espacio = Cobrar / Confirmar · Esc = cerrar'); }
                }
                return;
            }
            if (e.key === '/' && !enTexto) {
                e.preventDefault();
                if (currentModule.value !== 'POS') cambiarModulo('POS');
                nextTick(() => { try { if (scannerInput.value) scannerInput.value.focus(); } catch(_){} });
                return;
            }
            if (e.altKey && (e.key === '1' || e.key === '2' || e.key === '3')) {
                e.preventDefault();
                cambiarModulo(e.key === '1' ? 'POS' : e.key === '2' ? 'CAJA' : 'TOOLS');
                return;
            }
        };
        try { esPC.value = !!(window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches); } catch(_) { esPC.value = false; }
        window.addEventListener('keydown', _atajosPC);

        // ════════════════════════════════════════════════════════════════════
        // [Modo Pro] Barra inferior AUTO-OCULTA → más espacio de trabajo. Colapsada = línea fina con los
        // colores de marca de cada módulo + dots de alerta (caja, etiquetas) visibles aunque chiquitos.
        // Expande con hover (PC) o tap (táctil); se vuelve a esconder a ~5s de inactividad o al navegar.
        // Se autoactiva en PC (autodetect) y se puede togglear desde Herramientas. NO se oculta sola un módulo
        // con alerta crítica (el dot late). Default: en PC arranca pro; en táctil normal (toggle disponible).
        // ════════════════════════════════════════════════════════════════════
        // [v2.8.41] posDisponible: ¿el POS puede vender ahora? (sin "_" → Vue lo expone en template)
        //  · cajero  → tiene SU caja abierta.   · vendedor → hay caja activa en su zona.
        //  null(desconocido)=optimista (no molesta en boot).  Definido ARRIBA del nav: programarColapso lo usa.
        const posDisponible = computed(() => {
            if (config.value.esCajero) return !!cajaAbierta.value;
            return cajeroActivoEnZona.value !== false;   // objeto=ok · null=desconocido(optimista) · false=sin caja
        });

        const modoPro = ref(false);
        const navColapsado = ref(false);
        let _navTimer = null;
        // setea el estado + la clase en body que REDUCE el pb-nav (sino el padding queda y no se gana espacio real)
        const _setNavColapsado = (v) => {
            navColapsado.value = !!v;
            try { document.body.classList.toggle('nav-colapsado-pro', !!v); } catch(_){}
        };
        const programarColapso = (ms) => {
            if (!modoPro.value) return;
            // [v2.8.42] Sin caja: el nav NO se comprime — queda estirado para llegar a Mis Ventas/Herramientas
            // (y para que el overlay del POS no deje ver los productos por el hueco del nav colapsado).
            if (!posDisponible.value) { if (_navTimer) clearTimeout(_navTimer); _setNavColapsado(false); return; }
            if (_navTimer) clearTimeout(_navTimer);
            _navTimer = setTimeout(() => { _setNavColapsado(true); }, ms || 5000);
        };
        const expandirNav = () => {
            if (!modoPro.value) return;
            if (navColapsado.value) { try { if (navigator.vibrate) navigator.vibrate(12); } catch(_){} }
            _setNavColapsado(false);
            programarColapso(5000);
        };
        const toggleModoPro = () => {
            modoPro.value = !modoPro.value;
            try { localStorage.setItem('me_modo_pro', modoPro.value ? '1' : '0'); } catch(_){}
            if (modoPro.value) { _setNavColapsado(false); programarColapso(3500); agregarToast('Modo Pro ✓', 'La barra se oculta para darte más espacio · pasa el mouse abajo o toca la línea'); }
            else { _setNavColapsado(false); if (_navTimer) clearTimeout(_navTimer); }
        };
        try {
            const _mp = localStorage.getItem('me_modo_pro');
            // autodetect: PC (hover+fino) O pantalla ≥600px (tablet) → la barra auto-oculta da espacio en ambos.
            // (los ATAJOS de teclado siguen solo en PC vía esPC; el auto-ocultar va en PC y tablet.)
            const esTabletOMas = !!(window.matchMedia && window.matchMedia('(min-width: 600px)').matches);
            modoPro.value = (_mp != null) ? (_mp === '1') : (esPC.value || esTabletOMas);
        } catch(_) { modoPro.value = esPC.value; }
        if (modoPro.value) programarColapso(3500);   // arranca expandida, colapsa a los 3.5s (para que la vean)
        // [v2.8.42] Al perder/recuperar caja: fuerza nav estirado mientras no se pueda vender; al reabrir, retoma auto-hide.
        watch(posDisponible, (v) => {
            if (!v) { try { if (_navTimer) clearTimeout(_navTimer); } catch(_){} _setNavColapsado(false); }
            else if (modoPro.value) { programarColapso(4000); }
        });

        // [Color por módulo] toda la app habla el color del módulo activo → cohesión con la barra colapsada.
        // POS=verde · CAJA/Mis Ventas=azul · TOOLS=naranja. (mismo lenguaje en header + nav + barra.)
        const colorModulo = computed(() =>
            currentModule.value === 'CAJA'  ? '#3b82f6'
          : currentModule.value === 'TOOLS' ? '#ea580c'
          :                                    '#10b981');

        // ── [v2.8.41] POS "en espera" (sin caja) — UX háptica + efectos (posDisponible se define arriba) ──
        const posTabsHint = ref(false);          // nudge a CAJA/TOOLS ("úsame mientras tanto")
        const posCajaAbreCelebra = ref(false);   // burst "¡caja abierta!"
        // Shake suave del ícono de espera (reusa .g-shake)
        const _posEsperaShake = () => {
            requestAnimationFrame(() => { try {
                const el = document.querySelector('[data-pos-espera-icon]');
                if (el) { el.classList.remove('g-shake'); void el.offsetWidth; el.classList.add('g-shake'); }
            } catch(_){} });
        };
        // Resalta los tabs disponibles 1 vez (re-disparable)
        const _dispararTabsHint = () => {
            posTabsHint.value = false;
            requestAnimationFrame(() => { posTabsHint.value = true; });
            setTimeout(() => { posTabsHint.value = false; }, 1300);
        };
        // El momento estrella: el cajero abrió caja → ya puedes vender
        const _celebrarCajaAbierta = () => {
            try { playVentaOK(); } catch(_){}
            try { if (navigator.vibrate) navigator.vibrate([10, 40, 10, 40, 90]); } catch(_){}
            posCajaAbreCelebra.value = false;
            requestAnimationFrame(() => { posCajaAbreCelebra.value = true; });
            setTimeout(() => { posCajaAbreCelebra.value = false; }, 1350);
        };
        // CTA "Reintentar ahora" con feedback suave
        const avisarReintentar = () => {
            try { if (navigator.vibrate) navigator.vibrate(12); } catch(_){}
            try { playBeepSuave?.(); } catch(_){}
            verificarCajeroActivo();
        };

        // ── [v2.8.46] Sistema de movimiento del NAV inferior ───────────────
        const navInd = ref({ left: 0, width: 0 });      // indicador líquido (firma)
        const navEntrada = ref(false);                  // entrada coreografiada (una vez)
        const _navColorMap = { POS: '#10b981', CAJA: '#3b82f6', TOOLS: '#ea580c' };
        // Posiciona el indicador bajo el tab activo (offsetLeft/Width = inmune a transforms de animación)
        const _posicionarNavInd = () => {
            nextTick(() => { try {
                const nav = document.querySelector('[data-nav-root]');
                const btn = nav && nav.querySelector('[data-navtab="' + currentModule.value + '"]');
                if (btn && btn.offsetWidth > 0) navInd.value = { left: btn.offsetLeft, width: btn.offsetWidth };
            } catch(_){} });
        };
        // Ripple de color desde el punto del toque
        const _navRipple = (ev, mod) => {
            try {
                const btn = ev && ev.currentTarget; if (!btn) return;
                const r = btn.getBoundingClientRect();
                const size = Math.max(r.width, r.height) * 1.15;
                const sp = document.createElement('span');
                sp.className = 'nav-ripple';
                sp.style.width = sp.style.height = size + 'px';
                sp.style.left = ((ev.clientX || (r.left + r.width / 2)) - r.left - size / 2) + 'px';
                sp.style.top  = ((ev.clientY || (r.top + r.height / 2)) - r.top - size / 2) + 'px';
                sp.style.color = _navColorMap[mod] || '#10b981';
                btn.appendChild(sp);
                setTimeout(() => { try { sp.remove(); } catch(_){} }, 650);
            } catch(_){}
        };
        // Tap de tab: háptico + ripple + navegación (cambiarModulo conserva su lógica de POS-sin-caja)
        const navTap = (ev, mod) => {
            try { if (navigator.vibrate) navigator.vibrate(14); } catch(_){}
            _navRipple(ev, mod);
            cambiarModulo(mod);
        };
        // Dispara la entrada coreografiada (cascada + barrido) una sola vez
        const _dispararNavEntrada = () => {
            navEntrada.value = false;
            nextTick(() => {
                _posicionarNavInd();
                requestAnimationFrame(() => { navEntrada.value = true; });
                setTimeout(() => { navEntrada.value = false; _posicionarNavInd(); }, 1200);
            });
        };
        watch(currentModule, () => _posicionarNavInd());
        watch(navColapsado, (v) => { if (!v) _posicionarNavInd(); });   // al expandir (Modo Pro) reubica
        watch(() => config.value.completado, (v) => { if (v) _dispararNavEntrada(); });
        onMounted(() => {
            _posicionarNavInd();
            setTimeout(_posicionarNavInd, 450);   // tras asentar layout/fuentes
            if (config.value && config.value.completado) _dispararNavEntrada();
            try { window.addEventListener('resize', _posicionarNavInd, { passive: true }); } catch(_){}
        });

        // ── Listeners de actividad ───────────────────────────
        ['touchstart', 'click', 'keydown', 'mousemove', 'scroll'].forEach(ev => {
            window.addEventListener(ev, _resetIdleTimer, { passive: true });
        });

        // ── Watchers para reactivar wake lock + idle al cambiar sesión
        watch(() => config.value.completado, (val) => {
            if (val) {
                _activarWakeLock();
                _resetIdleTimer();
            } else {
                _liberarWakeLock();
                if (idleScreen.value.visible) ocultarSalvapantalla();
                if (_idleTimer) { clearTimeout(_idleTimer); _idleTimer = null; }
            }
        }, { immediate: true });

        // ── Toggles persistentes ─────────────────────────────
        // [quirúrgico 2026-07-19] toggleWakeLock/toggleSaver/setSaverMinutos/setMetaDiaria eliminados: settings del salvapantalla sin UI (0 refs).

        const playWelcomeFanfare = () => {
            if (!soundEnabled.value) return;
            try {
                const ctx = _audioCtx(); if (!ctx) return;
                [
                    { t: 0.00, f: 523,  v: 0.7,  d: 0.18 },  // C5
                    { t: 0.15, f: 659,  v: 0.7,  d: 0.18 },  // E5
                    { t: 0.30, f: 784,  v: 0.75, d: 0.20 },  // G5
                    { t: 0.50, f: 1047, v: 0.85, d: 0.45 }   // C6 sostenida
                ].forEach(({ t, f, v, d }) => {
                    const osc = ctx.createOscillator(); const gain = ctx.createGain();
                    osc.connect(gain); gain.connect(ctx.destination);
                    osc.type = 'triangle';
                    osc.frequency.setValueAtTime(f, ctx.currentTime + t);
                    gain.gain.setValueAtTime(v, ctx.currentTime + t);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + t + d);
                    osc.start(ctx.currentTime + t); osc.stop(ctx.currentTime + t + d + 0.01);
                });
            } catch(e) {}
        };

        const _calcStreakSession = () => {
            const _now = new Date();
            const _today = _now.toDateString();
            const _yesterday = new Date(_now.getTime() - 86400000).toDateString();
            const _lastDate = localStorage.getItem('mosexpress_last_welcome_date');
            let _streak = parseInt(localStorage.getItem('mosexpress_streak') || '0');
            if (_lastDate === _today) {
                // mismo día → no incrementar racha
            } else if (_lastDate === _yesterday) {
                _streak = (_streak || 0) + 1;
            } else {
                _streak = 1;
            }
            localStorage.setItem('mosexpress_last_welcome_date', _today);
            localStorage.setItem('mosexpress_streak', String(_streak));
            const _sessions = parseInt(localStorage.getItem('mosexpress_sessions_total') || '0') + 1;
            localStorage.setItem('mosexpress_sessions_total', String(_sessions));
            return { streak: _streak, session: _sessions };
        };

        const _animateCount = (key, target, ms) => {
            const start = Date.now();
            const tick = () => {
                if (!welcomeOverlay.value.visible) return; // abortar si se cerró
                const e = Math.min(1, (Date.now() - start) / ms);
                const easeOut = 1 - Math.pow(1 - e, 3);
                if (key === 'ventasShown') {
                    welcomeOverlay.value.ventasShown = (target * easeOut).toFixed(2);
                } else {
                    welcomeOverlay.value[key] = Math.round(target * easeOut);
                }
                if (e < 1) requestAnimationFrame(tick);
                else {
                    if (key === 'ventasShown') welcomeOverlay.value.ventasShown = target.toFixed(2);
                    else welcomeOverlay.value[key] = target;
                }
            };
            requestAnimationFrame(tick);
        };

        const _typewriter = (texto, speed) => {
            welcomeOverlay.value.quoteShown = '';
            welcomeOverlay.value.typing = true;
            let i = 0;
            const tick = () => {
                if (!welcomeOverlay.value.visible) return;
                welcomeOverlay.value.quoteShown = texto.substring(0, i);
                i++;
                if (i <= texto.length) setTimeout(tick, speed);
                else welcomeOverlay.value.typing = false;
            };
            tick();
        };

        const triggerWelcome = () => {
            // Guard: si ya está visible (ej. doble disparo accidental), no re-abrir
            if (welcomeOverlay.value.visible) return;
            const nombre = (config.value.vendedor || 'Compañero').split(' ')[0];
            const iniciales = (config.value.vendedor || 'M').split(' ').map(p => p[0]).slice(0, 2).join('').toUpperCase();
            const rol = config.value.esCajero ? 'Cajero · Frente de batalla' : 'Vendedor · Frente de batalla';

            const h = new Date().getHours();
            let saludo, emoji;
            if (h >= 5 && h < 12)        { saludo = '¡Buenos días';   emoji = '☀️'; }
            else if (h >= 12 && h < 19)  { saludo = '¡Buenas tardes'; emoji = '🌤️'; }
            else                          { saludo = '¡Buenas noches'; emoji = '🌙'; }

            const dia = new Date().getDay();
            const { streak, session } = _calcStreakSession();
            let tag = null;
            if (streak >= 7)        tag = '🔥 RACHA DE FUEGO · ' + streak + ' días seguidos';
            else if (dia === 1)     tag = '💪 LUNES — empieza fuerte';
            else if (dia === 5)     tag = '🏆 VIERNES — recta final';
            else if (dia === 6)     tag = '⭐ SÁBADO — día de campeones';
            else if (dia === 0)     tag = '🌟 DOMINGO — turno especial';

            const quote = _frasesMotivacion[Math.floor(Math.random() * _frasesMotivacion.length)];
            // Buscar último cierre — solo mostrar si fue ayer u hoy temprano
            let ventasAyer = 0;
            try {
                const _last = JSON.parse(localStorage.getItem('mosexpress_ventas_ultimo_cierre') || 'null');
                if (_last && _last.fecha) {
                    const _yest = new Date(Date.now() - 86400000).toDateString();
                    if (_last.fecha === _yest || _last.fecha === new Date().toDateString()) {
                        ventasAyer = parseFloat(_last.total) || 0;
                    }
                }
            } catch(e) {}

            // Generar 60 piezas de confetti con posiciones/colores random
            const palette = ['#fbbf24', '#10b981', '#3b82f6', '#ec4899', '#f97316', '#a78bfa', '#22d3ee', '#fef08a'];
            const confetti = [];
            for (let i = 0; i < 60; i++) {
                confetti.push({
                    id: i,
                    left: Math.random() * 100,
                    dx: (Math.random() - 0.5) * 200,
                    color: palette[Math.floor(Math.random() * palette.length)],
                    delay: Math.random() * 1.5,
                    duration: 4 + Math.random() * 3
                });
            }
            const sparkles = [];
            for (let i = 0; i < 8; i++) {
                sparkles.push({ id: i, left: 5 + Math.random() * 90, top: 8 + Math.random() * 80, delay: Math.random() * 1.2 });
            }

            welcomeOverlay.value = {
                visible: true, fading: false,
                nombre, iniciales, rol, saludo, emoji, tag,
                quote, quoteShown: '', typing: false,
                streak, streakShown: 0,
                session, sessionShown: 0,
                ventasHoy: ventasAyer, ventasShown: '0.00',
                confetti, sparkles
            };

            playWelcomeFanfare();

            // Lanzar typewriter después del bounce-in del saludo
            setTimeout(() => _typewriter(quote, 28), 900);
            // Animar contadores
            setTimeout(() => {
                _animateCount('streakShown', streak, 1100);
                _animateCount('sessionShown', session, 1300);
                if (ventasAyer > 0) _animateCount('ventasShown', ventasAyer, 1400);
            }, 1100);

            // Sync silencioso del catálogo en segundo plano
            setTimeout(() => {
                if (typeof sincronizarCatalogoBase === 'function') {
                    sincronizarCatalogoBase().catch(() => {});
                }
            }, 300);
        };

        const dismissWelcome = () => {
            if (!welcomeOverlay.value.visible || welcomeOverlay.value.fading) return;
            welcomeOverlay.value.fading = true;
            setTimeout(() => {
                welcomeOverlay.value.visible = false;
                welcomeOverlay.value.fading = false;
                cambiarModulo('POS');
            }, 380);
        };

        // ── Pulso del card del catálogo cuando match exacto (visual de confirmación) ─
        const pulsingProductId = ref(null);
        let _pulseTimer = null;
        const pulseGridProduct = (idUnico) => {
            if (!idUnico) return;
            if (_pulseTimer) clearTimeout(_pulseTimer);
            pulsingProductId.value = null;
            nextTick(() => {
                pulsingProductId.value = idUnico;
                vibrate(45);
                _pulseTimer = setTimeout(() => {
                    if (pulsingProductId.value === idUnico) pulsingProductId.value = null;
                    _pulseTimer = null;
                }, 750);
            });
        };

        // ── Flash + badge "+1/-1" + scroll del item del carrito ─
        const flashCartItem = (idx, delta) => {
            if (idx < 0 || idx >= carrito.value.length) return;
            const item = carrito.value[idx];
            if (item._flashTimer) clearTimeout(item._flashTimer);
            item.flashing = false; item.qtyBadge = 0;
            nextTick(() => {
                item.flashing = true;
                item.qtyBadge = delta;
                item._flashTimer = setTimeout(() => {
                    item.flashing = false;
                    item.qtyBadge = 0;
                    item._flashTimer = null;
                }, 700);
                const el = document.querySelector('[data-cart-idx="' + idx + '"]');
                if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            });
        };

        // --- MODO CAJERO ---
        // ══════════════════════════════════════════════════════════════════════
        // MODO CAJERO v2 — la estación de cobro.
        //
        // Tres momentos: el radar (esperando), el ticket en mano y el cobrado.
        // El cajero NUNCA escribe: escanea con el lector (USB o bluetooth, los dos
        // escriben como un teclado) o toca el ticket en el riel. La cámara arranca
        // APAGADA y es de emergencia — con el lector el cobro es más rápido y el
        // escenario queda entero.
        //
        // El camino del DINERO es el mismo de siempre: se llena ventaCobrar +
        // pagoCobroPendiente y se llama a procesarCobroPendiente. Acá solo cambia
        // la puesta en escena; ni un céntimo pasa por código nuevo.
        // ══════════════════════════════════════════════════════════════════════
        const modoCajero      = ref(false);
        // Con la estación abierta la app NO se recarga sola por versión nueva: se sale por el ✕
        // y recién ahí se aplica. Un reload con un cliente enfrente y el ticket escaneado a
        // medias no es una actualización, es una venta perdida.
        watch(modoCajero, v => { _meBusyEstacion.value = !!v; }, { immediate: true });
        const cajeroBusqueda  = ref('');
        const cajeroTicketActual = ref(null);
        const cajeroCamara    = ref(false);
        const cajeroScannerInst = ref(null);
        const cajeroInput     = ref(null);
        const mcEstado    = ref('espera');     // espera · cobro · mixto · hecho
        const mcYapes     = ref([]);
        const mcEsperando = ref([]);
        const mcMixEfe    = ref('');
        const mcProcesando = ref(false);
        const mcReloj     = ref('');
        const mcHechoMonto = ref(0);
        const mcHechoTxt  = ref('');
        const mcReja=ref(null), mcAura=ref(null), mcFlash=ref(null);
        let _mcTimerRio = null, _mcTimerRel = null, _mcRaf = null, _mcRtTimer = null, _mcTimerVoz = null;

        /* ── helpers de pantalla ── */
        const mcMoney = v => 'S/ ' + (parseFloat(v) || 0).toFixed(2);
        const mcDigitos = v => String((parseFloat(v) || 0).toFixed(2)).split('');
        const mcPrimerNombre = n => String(n || '').trim().split(/\s+/)[0] || '';
        const mcTipoCorto = t => t === 'FACTURA' ? 'FAC' : t === 'BOLETA' ? 'BOL' : 'N.V.';
        const mcHora = v => { try { return new Date(v.timestamp).toTimeString().slice(0,5); } catch(_) { return v.hora || ''; } };

        // lo que falta cobrar de ESTA caja: ni anulado, ni ya cobrado, ni a crédito
        const mcPendientes = computed(() => (ventasZona.value || []).filter(v =>
            !v.anulada && !v.cobrado && !v.credito &&
            String(v.cobradoMetodo || v.raw_data?.header?.metodo || 'POR_COBRAR').toUpperCase() === 'POR_COBRAR'
        ));
        const mcTotalPend = computed(() => mcPendientes.value.reduce((a,v) => a + (parseFloat(v.total)||0), 0));
        const mcYapesLibres = computed(() => mcYapes.value.filter(y => y.estado === 'NUEVO' && !y.ilegible).length);

        // Yape libre que calza con un monto. A UN DECIMAL: Yape solo mueve un decimal,
        // así que un ticket de 5.54 lo paga un Yape de 5.5 — comparar exacto no serviría.
        const mcYapeLibrePara = monto => mcYapes.value.find(y =>
            y.estado === 'NUEVO' && !y.ilegible &&
            Math.round((parseFloat(y.monto)||0)*10) === Math.round((parseFloat(monto)||0)*10));
        const mcCalza = v => !!mcYapeLibrePara(v.total);
        const mcYapeCalza = y => y.estado === 'NUEVO' && !y.ilegible &&
            mcPendientes.value.some(v => Math.round((parseFloat(v.total)||0)*10) === Math.round((parseFloat(y.monto)||0)*10));
        const mcYapeDelTicket = computed(() => cajeroTicketActual.value ? mcYapeLibrePara(cajeroTicketActual.value.total) : null);
        /* ── LAS ÓRBITAS ──────────────────────────────────────────────────────
           Dos elipses centradas en el escenario. Cada elemento recibe su ángulo según cuántos
           haya (360/n): el espacio se reparte solo. Los tickets arrancan arriba y giran en
           sentido horario; los Yapes arrancan abajo y giran al revés, así nunca se cruzan en el
           mismo punto. Las medidas salen del tamaño real del escenario (ResizeObserver). Con un
           ticket en mano los anillos se abren para dejar sitio a la órbita de productos.
           ──────────────────────────────────────────────────────────────────── */
        const mcEscEl = ref(null);
        const mcEscSize = ref({ w: 1100, h: 640 });
        let _mcRO = null;
        watch(mcEscEl, el => {
            try { if (_mcRO) { _mcRO.disconnect(); _mcRO = null; } } catch(_) {}
            if (!el || typeof ResizeObserver === 'undefined') return;
            _mcRO = new ResizeObserver(() => { mcEscSize.value = { w: el.clientWidth || 1100, h: el.clientHeight || 640 }; });
            _mcRO.observe(el);
            mcEscSize.value = { w: el.clientWidth || 1100, h: el.clientHeight || 640 };
        });
        const _mcPos = (i, n, ring, sentido, abierto) => {
            const { w, h } = mcEscSize.value;
            // radios en proporción al escenario, con techo/piso para tablets chicas
            const rx = ring === 'tk' ? Math.min(w * .36, 470) + (abierto ? 30 : 0) : Math.min(w * .465, 600) + (abierto ? 22 : 0);
            const ry = ring === 'tk' ? Math.min(h * .36, 250) + (abierto ? 20 : 0) : Math.min(h * .44, 305) + (abierto ? 12 : 0);
            const paso = n > 0 ? 360 / n : 0;
            // Los dos anillos arrancan desfasados MEDIO paso: ningún satélite queda clavado justo
            // arriba (pegado a la barra) ni justo abajo (sobre la franja). Tickets giran horario
            // desde arriba; Yapes antihorario desde abajo, y con anillos distintos nunca coinciden.
            const base = ring === 'tk' ? -90 + paso / 2 : 90 + paso / 2;
            const ang = (base + sentido * i * paso) * Math.PI / 180;
            const x = Math.round(rx * Math.cos(ang)), y = Math.round(ry * Math.sin(ang));
            // profundidad: los de abajo (más cerca del observador) un poco más grandes
            const z = Math.round(40 * Math.sin(ang));
            return { st: { transform: 'translate3d(calc(-50% + ' + x + 'px), calc(-50% + ' + y + 'px), ' + z + 'px)' }, ang };
        };
        // los últimos 15 tickets: pendientes primero (encendidos), y cobrados de hoy para completar (apagados)
        const mcOrbTk = computed(() => {
            const abierto = mcEstado.value !== 'espera';
            const pend = mcPendientes.value.slice(0, 15);
            const hist = (ventasZona.value || [])
                .filter(v => v.cobrado && !v.anulada)
                .sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0))
                .slice(0, Math.max(0, 15 - pend.length));
            const todos = pend.map(v => ({ v, pend: true })).concat(hist.map(v => ({ v, pend: false })));
            const n = todos.length;
            // "lo que viene": el primer pendiente que no está en mano lleva la etiqueta SIGUIENTE
            const cur = cajeroTicketActual.value && cajeroTicketActual.value.id;
            const sig = pend.find(v => v.id !== cur);
            return todos.map((o, i) => Object.assign(o, _mcPos(i, n, 'tk', +1, abierto), { sig: !!(sig && o.v.id === sig.id) }));
        });
        // los últimos 15 Yapes, atados o no
        const mcOrbYp = computed(() => {
            const abierto = mcEstado.value !== 'espera';
            const ys = mcYapes.value.slice(0, 15);
            const n = ys.length;
            return ys.map((y, i) => Object.assign({ y }, _mcPos(i, n, 'yp', -1, abierto)));
        });
        // tocar un Yape no ata nada (eso es del sistema): solo ilumina el hilo hacia su ticket
        const mcTocarYape = (y) => {
            try {
                const ye = document.querySelector('#mcRoot .mc-yp[data-yp="' + y.id + '"]');
                let te = y.idVenta ? document.querySelector('#mcRoot .mc-tk[data-idv="' + y.idVenta + '"]') : null;
                if (!te && y.estado === 'NUEVO') te = document.querySelector('#mcRoot .mc-tk.calza');
                if (ye && te) { mcHazEntre(ye, te); mcSon('tick'); }
                else if (ye) { mcSon('tecla'); }
            } catch(_) {}
        };
        // la cola: los dos que vienen después del actual (o los dos primeros, si no hay actual)
        const mcSiguientes = computed(() => {
            const cur = cajeroTicketActual.value && cajeroTicketActual.value.id;
            return mcPendientes.value.filter(v => v.id !== cur).slice(0, 2);
        });
        // las líneas del ticket en mano: nombre, cantidad, subtotal (RPC 873, best-effort)
        const mcLineas = ref([]);
        const mcCant = it => { const n = parseFloat(it.cantidad) || 0; const um = String(it.um || 'NIU').toUpperCase();
            return (Number.isInteger(n) ? n : n.toFixed(3).replace(/0+$/, '').replace(/\.$/, '')) + (um === 'KGM' ? ' kg' : um === 'NIU' ? '×' : ' ' + um.toLowerCase()); };
        const mcCorto = n => { const t = String(n || '').replace(/\s+/g, ' ').trim(); return t.length > 26 ? t.slice(0, 25) + '…' : t; };
        async function mcCargarLineas(venta) {
            mcLineas.value = [];
            try {
                const tk = await _mintTokenSB(); if (!tk) return;
                const idVenta = venta.id_venta_gas || venta.id;
                const r = await _meFetchTimeout(`${SUPABASE_URL}/rest/v1/rpc/venta_lineas`, {
                    method: 'POST',
                    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + tk,
                               'Content-Profile': 'me', 'Content-Type': 'application/json' },
                    body: JSON.stringify({ p: { idVenta } })
                }, 6000);
                const d = await r.json().catch(() => null);
                // solo si el ticket en mano sigue siendo el mismo
                if (d && d.ok && Array.isArray(d.data) && cajeroTicketActual.value && cajeroTicketActual.value.id === venta.id)
                    mcLineas.value = d.data.slice(0, 8);
            } catch (_) {}
        }

        /* ── mixto ── */
        const mcMixEfeNum = computed(() => Math.min(parseFloat(mcMixEfe.value || 0) || 0,
                                                    cajeroTicketActual.value?.total || 0));
        const mcMixVir = computed(() => Math.max(0, +(((cajeroTicketActual.value?.total || 0) - mcMixEfeNum.value).toFixed(2))));
        const mcMixPct = computed(() => { const t = cajeroTicketActual.value?.total || 0;
            return t ? Math.round(mcMixEfeNum.value / t * 100) : 0; });
        const mcMixValido = computed(() => mcMixEfeNum.value > 0 && mcMixEfeNum.value < (cajeroTicketActual.value?.total || 0));
        const mcAbrirMixto = () => { mcMixEfe.value = ''; mcEstado.value = 'mixto'; };
        const mcTecla = k => {
            mcSon('tecla');
            if (k === '←') mcMixEfe.value = mcMixEfe.value.slice(0, -1);
            else if (k === '.') { if (!mcMixEfe.value.includes('.')) mcMixEfe.value = (mcMixEfe.value || '0') + '.'; }
            else mcMixEfe.value = (mcMixEfe.value + k).replace(/^0(\d)/, '$1');
        };

        /* ── sonidos: sintetizados, con dirección estéreo ── */
        let _mcAc;
        function mcTono(f1, f2, dur, vol, tipo, pan) {
            if (!voiceEnabled.value) return;
            try {
                _mcAc = _mcAc || new (window.AudioContext || window.webkitAudioContext)();
                const o = _mcAc.createOscillator(), g = _mcAc.createGain(), t = _mcAc.currentTime;
                let dst = g;
                if (_mcAc.createStereoPanner && pan) { const pn = _mcAc.createStereoPanner(); pn.pan.value = pan; g.connect(pn); dst = pn; }
                o.type = tipo || 'sine'; o.frequency.setValueAtTime(f1, t);
                if (f2) o.frequency.exponentialRampToValueAtTime(f2, t + dur);
                g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
                o.connect(g); dst.connect(_mcAc.destination); o.start(t); o.stop(t + dur + .02);
            } catch(_) {}
        }
        function mcSon(q) {
            if (q === 'tick')  return mcTono(880,1240,.07,.05,'triangle',-.6);
            if (q === 'blip')  { mcTono(520,1080,.13,.09,'square',0); return setTimeout(()=>mcTono(1400,0,.07,.04,'sine',0),60); }
            if (q === 'coin')  { mcTono(1180,0,.09,.07,'triangle',.65); return setTimeout(()=>mcTono(1620,0,.15,.06,'triangle',.65),70); }
            if (q === 'caja')  { mcTono(900,0,.07,.10,'square',0); setTimeout(()=>mcTono(1450,0,.1,.09,'square',0),75);
                                 return setTimeout(()=>mcTono(2200,900,.34,.07,'triangle',0),150); }
            if (q === 'match') return [660,880,1320,1760].forEach((f,i)=>setTimeout(()=>mcTono(f,0,.14,.055,'sine',(i-1.5)*.3), i*85));
            if (q === 'tecla') return mcTono(1500,0,.035,.035,'sine',0);
            if (q === 'error') return mcTono(220,140,.28,.07,'square',0);
        }
        function mcPulso(color) {
            try {
                if (color && document.getElementById('mcRoot')) document.getElementById('mcRoot').style.setProperty('--aura', color);
                if (mcReja.value) { mcReja.value.classList.add('on'); setTimeout(()=>mcReja.value && mcReja.value.classList.remove('on'), 600); }
                if (mcAura.value) { mcAura.value.classList.add('on'); setTimeout(()=>mcAura.value && mcAura.value.classList.remove('on'), 600); }
            } catch(_) {}
        }

        function mcPantallaCompleta() {
            try {
                const el = document.documentElement;
                const f = el.requestFullscreen || el.webkitRequestFullscreen || el.msRequestFullscreen;
                if (f && !document.fullscreenElement) f.call(el).catch(() => {});
            } catch(_) {}
        }
        // Si el cajero sale de pantalla completa con ESC, la estación NO se cierra: ESC es del
        // navegador, no una orden de dejar de cobrar. Se sale solo por el ✕.

        /* ── el escenario ── */
        const resetearCajero = () => {
            cajeroTicketActual.value = null;
            mcLineas.value = [];
            cajeroBusqueda.value = '';
            mcMixEfe.value = '';
            if (mcEstado.value !== 'hecho') mcEstado.value = 'espera';
            nextTick(() => {
                mcSoltarFoco();
                if (cajeroScannerInst.value && cajeroCamara.value) { try { cajeroScannerInst.value.resume(); } catch(_){} }
            });
        };

        // "Son cinco soles con sesenta": la frase que pediste para la estación. El POS dice el
        // número pelado; acá la tablet le habla al cliente.
        const mcDecirMonto = (monto) => {
            try {
                if (!voiceEnabled.value || !window.speechSynthesis) return;
                const soles = Math.floor(monto), cent = Math.round((monto - soles) * 100);
                let txt = 'Son ' + (soles === 1 ? 'un sol' : numALetras(soles) + ' soles');
                if (cent > 0) txt += ' con ' + numALetras(cent);
                const u = new SpeechSynthesisUtterance(txt); u.lang = 'es-PE'; u.rate = 0.95; u.pitch = 1.05;
                try { const voz = _seleccionarVoz(); if (voz) u.voice = voz; } catch (_) {}
                // cancel()+speak() pegados en Android retrasa o traga la frase: si hablaba, un respiro
                const decir = () => { try { speechSynthesis.speak(u); _ttsUltimo = Date.now(); } catch (_) {} };
                if (speechSynthesis.speaking || speechSynthesis.pending) { speechSynthesis.cancel(); setTimeout(decir, 60); }
                else decir();
            } catch (_) { try { leerMontoEnVoz(monto); } catch (__) {} }
        };
        // La voz NO se enfría en la estación: cada 8 s un utterance mudo (volume 0) mantiene el
        // motor despierto si no habló en los últimos 7 s. Igual truco que el POS (v2.8.245), donde
        // "la primera vez demora y después es instantáneo".
        let _mcTimerWarm = null;
        function _mcVozCaliente() {
            try {
                if (!voiceEnabled.value || !('speechSynthesis' in window)) return;
                // Chrome a veces deja el motor en PAUSA tras un cambio de foco/pestaña: resume() es inocuo si no.
                try { if (speechSynthesis.paused) speechSynthesis.resume(); } catch (_) {}
                // atasco: "speaking" desde hace más de 20 s (ninguna frase real dura eso) → se cancela
                if ((speechSynthesis.speaking || speechSynthesis.pending) && Date.now() - _ttsUltimo > 20000) { try { speechSynthesis.cancel(); } catch (_) {} }
                if (speechSynthesis.speaking || speechSynthesis.pending) return;
                if (Date.now() - _ttsUltimo < 7000) return;
                const u = new SpeechSynthesisUtterance(' '); u.lang = 'es-PE'; u.volume = 0; u.rate = 2;
                const voz = _seleccionarVoz(); if (voz) u.voice = voz;
                speechSynthesis.speak(u); _ttsUltimo = Date.now();
            } catch (_) {}
        }
        // El cierre del ciclo, hablado: el cliente oye con qué se cobró y que terminó.
        const mcDecirCobrado = (metodo) => {
            try {
                if (!voiceEnabled.value || !window.speechSynthesis) return;
                const como = metodo === 'EFECTIVO' ? 'efectivo' : metodo === 'VIRTUAL' ? 'virtual' : metodo === 'MIXTO' ? 'mixto' : String(metodo || '').toLowerCase();
                const u = new SpeechSynthesisUtterance('Pago ' + como + ', muchas gracias por su compra');
                u.lang = 'es-PE'; u.rate = 0.98; u.pitch = 1.05;
                try { const voz = _seleccionarVoz(); if (voz) u.voice = voz; } catch (_) {}
                const decir = () => { try { speechSynthesis.speak(u); _ttsUltimo = Date.now(); } catch (_) {} };
                if (speechSynthesis.speaking || speechSynthesis.pending) { speechSynthesis.cancel(); setTimeout(decir, 60); }
                else setTimeout(decir, 120);   // tras el sonido de caja
            } catch (_) {}
        };
        // Los botones de cobro reaccionan al primer toque. Un solo disparo por toque (el navegador
        // puede mandar pointerdown + click): se ignora cualquier repetición en 500 ms.
        let _mcTocoT = 0;
        const mcTocarCobro = (e, metodo) => {
            try { if (e && e.pointerType === 'mouse' && e.button !== 0) return; } catch (_) {}
            const now = Date.now(); if (now - _mcTocoT < 500) return; _mcTocoT = now;
            if (mcProcesando.value) return;
            try { navigator.vibrate && navigator.vibrate(12); } catch (_) {}
            if (metodo === 'MIXTO') mcAbrirMixto(); else mcCobrar(metodo);
        };
        const mcTomar = (venta) => {
            if (!venta) return;
            mcSon('blip'); mcPulso('#ffd166');
            try { if (mcFlash.value) { mcFlash.value.classList.add('on'); setTimeout(()=>mcFlash.value && mcFlash.value.classList.remove('on'), 340); } } catch(_){}
            try { const el = document.querySelector('[data-tk="' + venta.id + '"]');
                  if (el) { el.classList.add('vuela'); setTimeout(()=>el.classList.remove('vuela'), 520); } } catch(_){}
            cajeroTicketActual.value = venta;
            mcEstado.value = 'cobro';
            mcBarrido();
            mcCargarLineas(venta);
            mcDecirMonto(venta.total);
            if (cajeroScannerInst.value) { try { cajeroScannerInst.value.pause(true); } catch(_){} }
        };

        /**
         * El escaneo. Entiende TRES cosas:
         *   · el correlativo suelto (nota de venta)                → NVM2-000531
         *   · la cadena SUNAT del QR de un CPE                     → RUC|01|FM01|000053|…
         *   · el ref_local de un ticket impreso sin conexión
         * Sin lo del medio, boletas y facturas no se podían escanear: su QR trae la
         * cadena fiscal, no el correlativo.
         */
        const mcClaveDeEscaneo = (q) => {
            const t = String(q || '').trim();
            if (!t) return '';
            // La cadena SUNAT se reconoce por su FORMA: RUC (11 dígitos) · tipo (01 factura,
            // 03 boleta, 07/08 notas) · serie · número. Se parte por cualquier separador, no
            // solo "|": en un teclado ES-LatAm el lector puede mandar otro carácter para la
            // barra (ya pasó con el "-"), y con espacios alrededor. Un correlativo suelto
            // (NVM2-000531) no tiene esa forma y pasa tal cual.
            const tk = t.split(/[^0-9A-Za-z]+/).filter(Boolean);
            if (tk.length >= 4 && /^\d{11}$/.test(tk[0]) && /^0[1378]$/.test(tk[1]) && /^[A-Za-z0-9]{4}$/.test(tk[2]) && /^\d+$/.test(tk[3])) {
                return (tk[2] + '-' + tk[3].padStart(6, '0')).toUpperCase();
            }
            return t.toUpperCase();
        };
        /* ── EL TECLADO DE LA ESTACIÓN ─────────────────────────────────────────────
           El lector escribe como un teclado. Con la estación abierta se escucha en la ventana
           (fase de captura, antes que cualquier input) y se reconoce el escaneo por RÁFAGA: teclas
           a ≤35 ms y un Enter. Tecleo humano (más lento) se ignora. No hay ningún campo con foco,
           así que ningún teclado en pantalla se levanta — "directo lee, nada más". Si algún input
           quedó con foco (el buscador del POS, por ejemplo), se le quita.
           ──────────────────────────────────────────────────────────────────── */
        let _mcBuf = '', _mcBufT0 = 0, _mcBufTimer = null;
        // El foco va al PROPIO escenario (#mcRoot, tabindex=-1). Es un div, no un input: recibe el
        // teclado del lector pero no levanta teclado en pantalla. Dejar el foco "en la nada" (blur a
        // todo) parecía lo mismo y no lo es: en Android, sin ningún elemento enfocado, Chrome no
        // entrega los keydown de un teclado Bluetooth a la página — el lector chillaba y la estación
        // no recibía nada.
        const mcRootEl = ref(null);
        function mcSoltarFoco() {
            try {
                const ae = document.activeElement;
                if (ae && ae.closest && ae.closest('#mcRoot .mc-te')) return;   // tecla del mixto: no interrumpir
                // el sumidero primero: es un input (recibe keydown Y texto de IME); readonly +
                // inputmode=none → Android no levanta teclado. Si no existe, el escenario.
                const sm = mcSumidero.value || document.getElementById('mcSumidero');
                const r = mcRootEl.value || document.getElementById('mcRoot');
                // SOLO en espera: un input editable enfocado abre el IME de Android (ícono de
                // teclado, redibujo en negro al re-enfocar, teclado que amaga con salir). Mientras
                // se cobra, el foco va al escenario (div) y el sumidero se cierra.
                if (sm && mcEstado.value === 'espera') { if (ae !== sm) sm.focus({ preventScroll: true }); return; }
                if (sm) { try { sm.readOnly = true; if (ae === sm) sm.blur(); } catch (_) {} }
                if (r && ae !== r) { r.focus({ preventScroll: true }); }
            } catch(_) {}
        }
        // cada cambio de estado recoloca el foco: espera → sumidero · cobro/mixto/hecho → escenario
        watch(mcEstado, () => { nextTick(mcSoltarFoco); });
        // Lee la tecla de forma robusta: en Android algunos lectores Bluetooth/USB mandan e.key =
        // 'Unidentified' y solo e.keyCode / e.code traen la letra. El del salvapantallas (que sí
        // funciona en la tablet) mira e.key; acá se cubren los tres caminos.
        function _mcTeclaDe(e) {
            if (e.code === 'Minus' || e.code === 'NumpadSubtract') return '-';
            let k = e.key;
            if (!k || k === 'Unidentified' || k === 'Dead') {
                const c = String(e.code || '');
                if (/^Key[A-Z]$/.test(c)) k = c.slice(3);
                else if (/^(Digit|Numpad)[0-9]$/.test(c)) k = c.slice(-1);
                else if (c === 'Space') k = ' ';
                else if (c === 'Slash' || c === 'NumpadDivide') k = '/';
                else if (c === 'Period' || c === 'NumpadDecimal') k = '.';
                else if (c === 'Backslash' || c === 'IntlBackslash') k = '|';
                else if (e.keyCode >= 48 && e.keyCode <= 90) k = String.fromCharCode(e.keyCode);
            }
            return k;
        }
        // ── el SUMIDERO: input mudo que recibe texto de lectores que escriben como IME ──
        const mcSumidero = ref(null);
        const mcSumideroTxt = ref('');
        let _mcSumTimer = null;
        // ¿El sumidero es editable? READONLY por defecto: un campo editable enfocado + teclado físico
        // (el lector) hace que Android muestre el chip flotante de teclado/idioma. Solo se vuelve
        // editable si el lector escribe por el IME (se detecta en el captor) — y se recuerda.
        let _mcSumEditable = false;
        try { _mcSumEditable = localStorage.getItem('mc_sumidero_editable') === '1'; } catch (_) {}
        function _mcSumHacerEditable(por) {
            if (_mcSumEditable) return;
            _mcSumEditable = true; mcSumEditableVer.value = true;
            try { localStorage.setItem('mc_sumidero_editable', '1'); } catch (_) {}
            try { const el = mcSumidero.value; if (el && mcEstado.value === 'espera') el.readOnly = false; } catch (_) {}
            _mcOjoAnota({ key: por, code: 'sumidero→editable', keyCode: 0 }, 'modo');
        }
        const mcSumEditableVer = ref(_mcSumEditable);
        function mcSumCambiarModo() {   // desde el OJO: el cajero/dueño fuerza el modo si el automático no acertó
            _mcSumEditable = !_mcSumEditable; mcSumEditableVer.value = _mcSumEditable;
            try { localStorage.setItem('mc_sumidero_editable', _mcSumEditable ? '1' : '0'); } catch (_) {}
            try { const el = mcSumidero.value; if (el) { el.readOnly = !(mcEstado.value === 'espera' && _mcSumEditable); if (mcEstado.value === 'espera') { el.blur(); el.focus({ preventScroll: true }); } } } catch (_) {}
            _mcOjoAnota({ key: 'manual', code: _mcSumEditable ? 'sumidero→editable' : 'sumidero→readonly', keyCode: 0 }, 'modo');
        }
        function mcSumideroFoco() { /* en espera y si el lector escribe por IME: editable (sin teclado: inputmode=none) */
            try { const el = mcSumidero.value; if (el) { el.readOnly = !(mcEstado.value === 'espera' && _mcSumEditable); } } catch(_) {} }
        let _mcSumDrenHasta = 0;   // tras entregar, lo que siga llegando del mismo escaneo se descarta
        function mcSumideroEntrega() {
            const el = mcSumidero.value; if (!el) return;
            if (_mcSumTimer) { clearTimeout(_mcSumTimer); _mcSumTimer = null; }
            const v = String(el.value || '').trim();
            el.value = ''; mcSumideroTxt.value = v;
            if (v.length >= 4) { _mcSumDrenHasta = Date.now() + 900; mcSon('tecla'); cajeroBusqueda.value = v; buscarTicketCajero(); }
        }
        // El QR de un CPE es "RUC | 01 | SERIE | NÚMERO | igv | total | fecha | ...": en cuanto
        // llegó el separador que sigue al número ya se sabe qué ticket es. No se espera el resto.
        const _MC_QR_LISTO = /(?:^|\|)\s*[A-Za-z]{1,4}\d{1,2}\s*\|\s*\d{1,8}\s*\|/;
        function mcSumideroInput() {
            const el = mcSumidero.value; if (!el) return;
            const v = String(el.value || '');
            // cola del escaneo ya entregado: se descarta, y mientras siga llegando se sigue drenando
            // (cada carácter renueva 400 ms); recién con silencio vuelve a escuchar
            if (Date.now() < _mcSumDrenHasta) { el.value = ''; _mcSumDrenHasta = Date.now() + 400; return; }
            mcSumideroTxt.value = v;
            _mcOjoAnota({ key: v.slice(-1), code: 'input', keyCode: 0 }, 'input');
            if (_mcSumTimer) clearTimeout(_mcSumTimer);
            if (_MC_QR_LISTO.test(v)) { mcSumideroEntrega(); return; }         // QR: serie y número completos → ya
            _mcSumTimer = setTimeout(mcSumideroEntrega, 180);   // si el lector no manda Enter, 180 ms de silencio entregan
        }
        function mcSumideroEnter() { if (_mcSumTimer) { clearTimeout(_mcSumTimer); _mcSumTimer = null; } mcSumideroEntrega(); }

        // ── el OJO de diagnóstico: se anota cada tecla que llega (o no) a la estación ──
        const mcOjo = ref([]);
        const mcOjoVer = ref(false);
        function _mcOjoAnota(e, via) {
            try {
                mcOjo.value.unshift({ t: new Date().toTimeString().slice(3, 8), via, key: String(e.key), code: String(e.code || ''), kc: e.keyCode | 0,
                                      ae: (document.activeElement && (document.activeElement.id || document.activeElement.tagName)) || '' });
                if (mcOjo.value.length > 40) mcOjo.value.length = 40;
            } catch (_) {}
        }
        window.addEventListener('keypress', e => { if (modoCajero.value) _mcOjoAnota(e, 'keypress'); }, true);
        document.addEventListener('beforeinput', e => { if (modoCajero.value) _mcOjoAnota({ key: String(e.data || ''), code: e.inputType, keyCode: 0 }, 'beforeinput'); }, true);

        function _mcTeclado(e) {
            if (!modoCajero.value) return;
            _mcOjoAnota(e, 'keydown');
            const ch = _mcTeclaDe(e);
            const now = Date.now();
            const _ae = document.activeElement;
            // el lector escribe por el IME (Android): keyCode 229 / Unidentified sin code. El captor no
            // ve letras; el sumidero tiene que ser editable para recibir el texto.
            if (_ae && _ae.id === 'mcSumidero' && (e.keyCode === 229 || ((e.key === 'Unidentified' || !e.key) && !e.code))) { _mcSumHacerEditable('kc' + (e.keyCode | 0)); return; }
            // cede al sumidero solo si es editable (si está readonly, las teclas las lee este captor)
            const enSumidero = !!(_ae && _ae.id === 'mcSumidero' && !_ae.readOnly);
            if (typeof ch === 'string' && ch.length === 1 && /^[0-9A-Za-z\-|./ ]$/.test(ch)) {
                if (!_mcBuf) _mcBufT0 = now;
                _mcBuf += ch;
                if (_mcBufTimer) clearTimeout(_mcBufTimer);
                if (enSumidero) { _mcBufTimer = setTimeout(() => { _mcBuf = ''; }, 400); return; }   // el input lo recibe; el Enter/silencio decide
                // MISMO criterio que el captor del salvapantallas, que sí lee en la tablet: el único
                // corte es el silencio de 400 ms entre teclas. La regla de "≤35 ms por tecla" que
                // había acá tiraba a la basura el escaneo real — en Android el lector entrega las
                // teclas más lento que un USB en PC, y la estación no reaccionaba "como si no lo
                // detectara".
                _mcBufTimer = setTimeout(() => { _mcBuf = ''; }, 400);
                e.preventDefault(); e.stopPropagation();                   // que NO llegue a ningún input
                return;
            }
            if ((e.key === 'Enter' || e.code === 'Enter' || e.code === 'NumpadEnter' || e.keyCode === 13) && _mcBuf.length >= 4) {
                if (enSumidero) { _mcBuf = ''; return; }   // lo entrega el sumidero (keyup.enter), no duplicar
                const cod = _mcBuf;
                _mcBuf = ''; if (_mcBufTimer) { clearTimeout(_mcBufTimer); _mcBufTimer = null; }
                e.preventDefault(); e.stopPropagation();
                mcSon('tecla');                                            // se oye que entró
                cajeroBusqueda.value = cod;
                buscarTicketCajero();
                return;
            }
            if (e.key === 'Escape') { e.preventDefault(); return; }        // ESC no cierra la estación
            if (e.key !== 'Enter') { _mcBuf = ''; if (_mcBufTimer) { clearTimeout(_mcBufTimer); _mcBufTimer = null; } }
        }
        window.addEventListener('keydown', _mcTeclado, true);   // capture: antes que el POS y que el captor de guías
        // y si algo intenta enfocar un input mientras la estación está abierta, se le quita
        document.addEventListener('focusin', (e) => {
            if (!modoCajero.value) return;
            const t = e.target;
            if (t && t.matches && t.matches('input,textarea') && !(t.closest && t.closest('#mcRoot'))) { try { t.blur(); mcSoltarFoco(); } catch(_) {} }
        }, true);

        // Resuelve un escaneo a un ticket, sin tocar nada. Se usa desde la estación y también
        // desde afuera, para saber si un código es un ticket antes de decidir a dónde llevarlo.
        const mcResolverTicket = (q) => {
            const txt = String(q || '').trim();
            if (!txt) return null;
            const clave = mcClaveDeEscaneo(txt);
            const norm = c => String(c || '').trim().toUpperCase();
            // coincidencia EXACTA primero. Nunca `includes`: tipear "55" no puede abrir
            // el cobro del primer ticket que contenga 55 — eso es plata mal asignada.
            let t = (ventasZona.value || []).find(v => norm(v.correlativo) === clave || (v.ref_local && v.ref_local === txt));
            if (!t) {
                const parc = (ventasZona.value || []).filter(v => norm(v.correlativo).endsWith(clave));
                if (parc.length === 1) t = parc[0];
            }
            return t || null;
        };
        const buscarTicketCajero = () => {
            const q = cajeroBusqueda.value.trim();
            if (!q) return;
            const t = mcResolverTicket(q);
            cajeroBusqueda.value = '';
            nextTick(mcSoltarFoco);
            if (!t) { mcSon('error');
                      // se muestra la clave que se dedujo Y el texto crudo: si el lector manda algo
                      // distinto de lo esperado, acá se ve sin adivinar
                      agregarToast('No encontrado · busqué ' + mcClaveDeEscaneo(q), 'llegó: ' + q.slice(0, 90), 'warning', 9000);
                      try { const u = new SpeechSynthesisUtterance('no lo encuentro'); u.lang='es-PE';
                            if (voiceEnabled.value) speechSynthesis.speak(u); } catch(_){}
                      return; }
            if (t.anulada) { mcSon('error'); agregarToast('Anulado', t.correlativo);
                try { const u=new SpeechSynthesisUtterance('ticket anulado'); u.lang='es-PE';
                      if (voiceEnabled.value){speechSynthesis.cancel();speechSynthesis.speak(u);} } catch(_){}
                return; }
            if (t.cobrado) { mcSon('error'); agregarToast('Ya cobrado', t.correlativo);
                try { const u=new SpeechSynthesisUtterance('ticket ya cobrado'); u.lang='es-PE';
                      if (voiceEnabled.value){speechSynthesis.cancel();speechSynthesis.speak(u);} } catch(_){}
                return; }
            mcTomar(t);
        };

        /**
         * COBRAR. Llena exactamente lo mismo que llenaba el modal viejo y llama a
         * procesarCobroPendiente: el dinero pasa por el camino probado de siempre.
         * `modalCobro` se deja en false a propósito — el modal viejo sigue vivo para
         * el flujo del vendedor, pero acá el escenario ya es la pantalla de cobro.
         */
        const mcCobrar = (metodo) => {
            const t = cajeroTicketActual.value;
            if (!t || mcProcesando.value) return;
            if (metodo === 'MIXTO' && !mcMixValido.value) return;
            mcProcesando.value = true;
            const yp = mcYapeDelTicket.value;
            const virtual = metodo === 'MIXTO' ? mcMixVir.value : 0;

            ventaCobrar.value = t;
            pagoCobroPendiente.value = { metodo, montoRecibido: t.total, montoVirtual: virtual };
            modalCobro.value = false;

            mcHechoMonto.value = t.total;
            const _base = (metodo === 'MIXTO'
                ? 'MIXTO · ' + mcMoney(mcMixEfeNum.value) + ' efectivo + ' + mcMoney(virtual) + ' virtual'
                : metodo);
            // El cajero NO ata el Yape (decisión del dueño): el sistema lo cuadra por monto y
            // ventana, y verificar / desverificar / soltar es del admin en MOS. Acá solo se dice
            // la verdad: hay un Yape a la vista que calza; el sistema lo cuadra solo.
            mcHechoTxt.value = _base + (metodo !== 'EFECTIVO' && yp
                ? ' · 💜 el Yape de ' + mcPrimerNombre(yp.pagador) + ' calza · el sistema lo cuadra solo' : '');

            mcSon('caja'); mcPulso('#3ddc84');
            // cierra el ciclo en voz alta: "Cobrado en efectivo, muchas gracias por su compra"
            mcDecirCobrado(metodo);
            try { navigator.vibrate && navigator.vibrate([18,40,18]); } catch(_){}
            try { const sh=document.createElement('div'); sh.className='mc-shock';
                  document.getElementById('mcRoot').appendChild(sh); setTimeout(()=>sh.remove(), 850); } catch(_){}

            try { procesarCobroPendiente(); } catch (e) { console.error('[cajero] cobro', e); }

            mcEstado.value = 'hecho';
            setTimeout(() => { mcProcesando.value = false; mcEstado.value = 'espera'; mcCargarRio(); }, 1350);
        };

        /* ── el río de Yapes: lista + voz ── */
        async function mcCargarRio() {
            if (!modoCajero.value) return;
            try {
                const tk = await _mintTokenSB(); if (!tk) return;
                const r = await _meFetchTimeout(`${SUPABASE_URL}/rest/v1/rpc/yapes_rio`, {
                    method: 'POST',
                    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + tk,
                               'Content-Profile': 'me', 'Content-Type': 'application/json' },
                    body: JSON.stringify({ p: { zona: config.value.zona || '', idCaja: idCajaActual.value || '', min: 120 } })
                }, 12000);
                const d = await r.json().catch(() => null);
                if (d && d.ok && d.data) {
                    const antes = mcYapes.value.length ? mcYapes.value[0].id : 0;
                    const esperabaAntes = new Set(mcEsperando.value.map(e => e.idVenta));
                    mcYapes.value = d.data.yapes || [];
                    mcEsperando.value = d.data.esperando || [];
                    // un ticket que estaba "esperando su Yape" y ya no está: se cuadró solo.
                    // Es la pantalla resolviendo algo delante del cajero — se ve y se oye.
                    if (esperabaAntes.size) {
                        const ahora = new Set(mcEsperando.value.map(e => e.idVenta));
                        const resueltos = [...esperabaAntes].filter(id => !ahora.has(id));
                        if (resueltos.length) { mcSon('match'); mcPulso('#3ddc84'); mcChispa(); }
                    }
                    if (mcYapes.value.length && mcYapes.value[0].id !== antes && antes) {
                        mcSon('coin'); mcPulso('#b07bff');
                        if (mcYapes.value.some(y => mcYapeCalza(y))) setTimeout(() => mcSon('match'), 400);
                    }
                }
            } catch(_) {}
        }

        /* ── cámara: emergencia, apagada por defecto ── */
        const iniciarCamaraCajero = () => {
            if (cajeroScannerInst.value || typeof Html5Qrcode === 'undefined') return;
            nextTick(() => {
                try {
                    const scanner = new Html5Qrcode('cajero-qr-reader');
                    cajeroScannerInst.value = scanner;
                    scanner.start({ facingMode: 'environment' }, { fps: 12, qrbox: { width: 190, height: 190 } },
                        (dec) => { cajeroBusqueda.value = dec; buscarTicketCajero(); }, () => {})
                    .catch(() => { cajeroCamara.value = false; cajeroScannerInst.value = null;
                                   agregarToast('Cámara', 'Revisá los permisos'); });
                } catch(_) { cajeroCamara.value = false; }
            });
        };
        const detenerCamaraCajero = () => {
            if (cajeroScannerInst.value) { try { cajeroScannerInst.value.stop().catch(()=>{}); } catch(_){} cajeroScannerInst.value = null; }
            cajeroCamara.value = false;
        };
        const mcToggleCamara = () => {
            cajeroCamara.value ? detenerCamaraCajero() : (cajeroCamara.value = true, iniciarCamaraCajero());
        };

        const detenerPollingWizard = () => {
            if (_wizardPollingTimer) { clearInterval(_wizardPollingTimer); _wizardPollingTimer = null; }
            // [v2.8.9] El polling de presencia vive ligado al wizard también.
            if (typeof _wizDetenerPollingPresencia === 'function') _wizDetenerPollingPresencia();
        };

        const verificarCajeroEnZonaWizard = async (zona, silent = false) => {
            if (!zona || API_URL === 'ENLACE_DE_TU_SCRIPT_GAS_AQUI') return;
            if (!silent) wizardVerificando.value = true;
            try {
                const d = await _meCajeroActivoZona(zona);
                wizardCajeroOcupado.value = !!(d && d.status === 'success' && d.activo);
                cajeroWizardInfo.value = wizardCajeroOcupado.value ? { vendedor: d.vendedor, idCaja: d.idCaja } : null;
                if (wizardCajeroOcupado.value) configWizard.value.esCajero = false;
            } catch(e) {
                wizardCajeroOcupado.value = false;
                cajeroWizardInfo.value = null;
            }
            finally { if (!silent) wizardVerificando.value = false; }
        };

        const seleccionarZonaWizard = async (zona) => {
            configWizard.value.zona = zona;
            configWizard.value.estacion = null;
            configWizard.value.esCajero = false;
            configWizard.value.monto = 0;
            // [v2.5.34] Usar precarga: si ya cargamos cajeros_activos_todos en el boot,
            // sabemos al instante si hay cajero en esta zona (no fetch en vivo).
            const cached = wizCajerosActivosPorZona.value && wizCajerosActivosPorZona.value[zona];
            if (cached) {
                wizardCajeroOcupado.value = true;
                cajeroWizardInfo.value = cached;
            } else {
                wizardCajeroOcupado.value = false;
                cajeroWizardInfo.value = null;
            }
            // Auto-seleccionar si hay una sola estación en la zona
            const estaciones = estacionesFiltradas.value;
            if (estaciones.length === 1) configWizard.value.estacion = estaciones[0];
            // Refresh en background (silent) para tener fresh state — no bloquea UI
            verificarCajeroEnZonaWizard(zona, true);
            // Polling 3s mientras el wizard está abierto
            detenerPollingWizard();
            if (!offlineMode.value && API_URL !== 'ENLACE_DE_TU_SCRIPT_GAS_AQUI') {
                _wizardPollingTimer = setInterval(() => {
                    verificarCajeroEnZonaWizard(configWizard.value.zona, true); // silent: no parpadea
                }, 3000);
            }
        };

        // ═══════════════════════════════════════════════════════════
        // [v2.5.33] WIZARD MODERNO — state, computed y métodos
        // ═══════════════════════════════════════════════════════════
        const wizStep = ref(1);
        const wizUltimosUsers = ref([]); // {nombre, color, esCajero, zona, estacion} ultimos 5
        const wizUltimoTurno = ref(null); // fast-track: ultimo turno hoy
        const wizMensajeJefe = ref(''); // mensaje opcional del jefe
        const wizClima = ref({ texto: '' });
        const wizCajerosActivosPorZona = ref({}); // { zonaId: { vendedor, idCaja, desde } }
        const wizPresenciaPorZona = ref({});      // { zonaId: { zona_nombre, cajero:{nombre,id_caja,desde}|null, vendedores:[{id_personal,nombre,estacion,desde}] } }
        let _wizPresenciaTimer = null;            // refresco de presencia mientras el wizard está abierto
        let _wizHeartbeatTimer = null;            // pulso registrar_presencia mientras el turno está activo
        const wizZonaExpandida = ref(null);       // zona_id con el panel +Cajero (monto) desplegado inline
        const wizZonaShake = ref(null);           // zona_id que hace shake (intento de 2º cajero)
        const wizImpresorasStatus = ref({}); // { printerId: { state, name, reason } }
        const wizMontoSugerido = ref(0);
        const wizProgreso = ref({ activo: false, pct: 0, pasos: [], actualIdx: 0 });
        const wizPreflight = ref({ run: false, mos: false, impresora: false, impresoraOk: false, catalogo: false });

        // ── Helpers visuales ──
        const _wizColorParaUser = (nombre) => {
            const n = String(nombre || '').toLowerCase();
            let h = 0;
            for (let i = 0; i < n.length; i++) h = (h * 31 + n.charCodeAt(i)) >>> 0;
            const colores = ['#10b981','#3b82f6','#f59e0b','#ef4444','#8b5cf6','#ec4899','#06b6d4','#84cc16','#f97316'];
            return colores[h % colores.length];
        };

        // ── SFX (sonidos sintetizados con Web Audio) ──
        let _wizAudioCtx = null;
        const wizBeep = (tipo = 'tap') => {
            try {
                if (!_wizAudioCtx) _wizAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
                const ctx = _wizAudioCtx;
                const presets = {
                    tap:     { freq: 800, dur: 0.05, vol: 0.08, type: 'sine' },
                    next:    { freq: 1200, dur: 0.08, vol: 0.10, type: 'sine' },
                    success: { freq: 1600, dur: 0.18, vol: 0.12, type: 'triangle' },
                    error:   { freq: 200, dur: 0.20, vol: 0.10, type: 'sawtooth' }
                };
                const p = presets[tipo] || presets.tap;
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = p.type; osc.frequency.value = p.freq;
                gain.gain.value = p.vol;
                osc.connect(gain).connect(ctx.destination);
                osc.start();
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + p.dur);
                osc.stop(ctx.currentTime + p.dur);
            } catch(e) {}
        };

        // ── Saludo según hora ──
        const wizSaludo = computed(() => {
            const h = new Date().getHours();
            if (h < 6)  return '✨ Buenas madrugadas';
            if (h < 12) return '☀ Buenos días';
            if (h < 19) return '🌤 Buenas tardes';
            return '🌙 Buenas noches';
        });
        const wizTitulo = computed(() => {
            // [v2.8.9] 3 pasos: ¿Quién? · Tienda viva · Estación
            const titulos = ['', 'Inicia tu turno', 'Elige tu tienda', 'Tu caja'];
            return titulos[wizStep.value] || 'Iniciar';
        });

        // ── Helper: "hace Xh Ym" desde un ISO ──
        const _wizHaceTexto = (iso) => {
            if (!iso) return '';
            const ms = Date.now() - new Date(iso).getTime();
            if (isNaN(ms) || ms < 0) return '';
            const horas = Math.floor(ms / 3600000);
            const mins  = Math.floor((ms % 3600000) / 60000);
            return horas > 0 ? `hace ${horas}h ${mins}m` : `hace ${mins}m`;
        };
        const _wizIniciales = (nombre) => {
            const partes = String(nombre || '?').trim().split(/\s+/);
            const a = (partes[0] || '?')[0] || '?';
            const b = partes.length > 1 ? (partes[partes.length - 1][0] || '') : '';
            return (a + b).toUpperCase();
        };

        // ── Zonas como TIENDAS VIVAS (cajero corona + vendedores) ──
        // Fuente preferida: presencia_por_zona (cajero server-side + vendedores
        // heartbeat). Fallback: wizCajerosActivosPorZona (GAS cajeros_activos_todos).
        // NUNCA expone id_caja en el login (confunde/alarma al operador).
        const wizZonasInfo = computed(() => {
            return zonasUnicas.value.map(z => {
                const ests = (db.value.ZONAS_CONFIG || []).filter(x => x.Zona_ID === z);
                const pres = wizPresenciaPorZona.value[z];
                // Cajero: 1º de presencia (server-side), 2º del cache GAS.
                let cajeroNombre = '', cajeroDesde = '';
                if (pres && pres.cajero) {
                    cajeroNombre = pres.cajero.nombre || '';
                    // La RPC ya filtra por pulso <90s → quien aparece está EN VIVO. Antes mostrábamos la
                    // hora de apertura de caja (ej. "hace 4h30") y parecía viejo/no-real-time. Ahora "en línea".
                    cajeroDesde  = '🟢 en línea';
                } else {
                    const cg = wizCajerosActivosPorZona.value[z];
                    if (cg) { cajeroNombre = cg.vendedor || cg.nombre || ''; cajeroDesde = _wizHaceTexto(cg.desde); }
                }
                const cajeroActivo = !!cajeroNombre;
                const vendedores = (pres && Array.isArray(pres.vendedores) ? pres.vendedores : []).map(v => ({
                    nombre: v.nombre || '?',
                    estacion: v.estacion || '',
                    color: _wizColorParaUser(v.nombre),
                    iniciales: _wizIniciales(v.nombre),
                    desde: _wizHaceTexto(v.desde)
                }));
                const dentro = (cajeroActivo ? 1 : 0) + vendedores.length;
                return {
                    zona: z,
                    zonaNombre: (pres && pres.zona_nombre) || z,
                    cantEstaciones: ests.length,
                    cajeroActivo,
                    cajeroNombre,
                    cajeroColor: cajeroActivo ? _wizColorParaUser(cajeroNombre) : '',
                    cajeroIniciales: cajeroActivo ? _wizIniciales(cajeroNombre) : '',
                    cajeroDesde,
                    vendedores,
                    dentro,                       // total de personas en la tienda
                    estadoChip: dentro > 0 ? `· ${dentro} dentro` : '· libre'
                };
            });
        });

        // ── Estaciones con metadata (impresora live + users) ──
        const wizEstacionesInfo = computed(() => {
            return estacionesFiltradas.value.map(est => {
                const pid = String(est.PrintNode_ID || '').trim();
                const imp = wizImpresorasStatus.value[pid];
                let impIcon = '⚪', impStateClass = 'bg-gray-50 text-gray-500 border border-gray-200', impReason = 'Consultando...';
                if (!pid) {
                    impIcon = '🚫'; impStateClass = 'bg-gray-100 text-gray-500 border border-gray-200'; impReason = 'No configurada';
                } else if (imp) {
                    if (imp.state === 'online') { impIcon = '🟢'; impStateClass = 'bg-emerald-50 text-emerald-700 border border-emerald-200'; impReason = imp.reason || 'Lista para imprimir'; }
                    else if (imp.state === 'offline') { impIcon = '🔴'; impStateClass = 'bg-red-50 text-red-700 border border-red-200'; impReason = imp.reason || 'Apagada / sin conexión'; }
                    else { impIcon = '🟡'; impStateClass = 'bg-amber-50 text-amber-700 border border-amber-200'; impReason = imp.reason || 'Verificando...'; }
                }
                return {
                    estacion: est,
                    impNombre: imp?.name || ('Impresora #' + pid),
                    impIcon, impStateClass, impReason,
                    usersActivos: [] // placeholder, se llena con polling si hay endpoint
                };
            });
        });

        // ── Cargar cajeros activos por zona (bulk) ──
        const _wizCargarCajerosActivos = async () => {
            try {
                if (offlineMode.value || API_URL === 'ENLACE_DE_TU_SCRIPT_GAS_AQUI') return;
                // [cero-GAS] cajeros activos por zona directo a Supabase. Mismo shape {status,porZona}.
                // Ante error/sin token → no tocar wizCajerosActivosPorZona.
                const tk = await _mintTokenSB();
                if (!tk) return;
                const r = await _meFetchTimeout(`${SUPABASE_URL}/rest/v1/rpc/cajeros_activos_todos`, {
                    method: 'POST',
                    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + tk, 'Content-Profile': 'me', 'Content-Type': 'application/json' },
                    body: JSON.stringify({ p: {} })
                }, 8000);
                const d = await r.json().catch(() => null);
                if (r.ok && d && d.status === 'success' && d.porZona) {
                    wizCajerosActivosPorZona.value = d.porZona;
                }
            } catch(e) {}
        };

        // ── [v2.8.9] Presencia EN VIVO por zona (cajero corona + vendedores) ──
        // DIRECTO a Supabase (patrón _ventasZonaDirecto). El cajero viene server-side
        // (me.cajas ABIERTA), los vendedores del heartbeat. Si falla, el computed cae
        // de forma transparente al cache GAS de cajeros — el login NUNCA se bloquea.
        const _wizCargarPresencia = async () => {
            if (offlineMode.value || API_URL === 'ENLACE_DE_TU_SCRIPT_GAS_AQUI') return;
            try {
                const token = await _mintTokenSB();
                const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/presencia_por_zona`, {
                    method: 'POST',
                    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + token, 'Content-Profile': 'me', 'Content-Type': 'application/json' },
                    body: JSON.stringify({})
                });
                if (!res.ok) return;
                const d = await res.json();
                if (d && typeof d === 'object') wizPresenciaPorZona.value = d;
            } catch (e) { /* silencioso: el computed usa fallback GAS */ }
        };
        const _wizIniciarPollingPresencia = () => {
            _wizCargarPresencia();
            if (_wizPresenciaTimer) clearInterval(_wizPresenciaTimer);
            if (!offlineMode.value && API_URL !== 'ENLACE_DE_TU_SCRIPT_GAS_AQUI') {
                _wizPresenciaTimer = setInterval(_wizCargarPresencia, 2000);  // [fix rezago] 4s→2s: presencia mas viva
            }
        };
        const _wizDetenerPollingPresencia = () => {
            if (_wizPresenciaTimer) { clearInterval(_wizPresenciaTimer); _wizPresenciaTimer = null; }
        };

        // ── [v2.8.191] Día de negocio SIEMPRE en TZ Perú (regla del ecosistema:
        // espeja el backend, que corta el día en America/Lima). Un equipo con el
        // reloj/TZ mal configurado ya no se auto-desloguea a mitad de jornada.
        // 'mosexpress_session_dia' (Lima, YYYY-MM-DD) es la marca canónica; el
        // viejo session_date (toDateString local) queda de fallback transicional. ──
        const _meDiaLima = () => { try { return new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Lima' }).format(new Date()); } catch(e) { return new Date().toISOString().slice(0,10); } };
        const _meSesionEsDeHoy = () => {
            try {
                const dLima = localStorage.getItem('mosexpress_session_dia');
                if (dLima) return dLima === _meDiaLima();
                return localStorage.getItem('mosexpress_session_date') === new Date().toDateString();
            } catch(e) { return true; }   // fail-open: ante duda no matar la sesión
        };
        // ── [v2.8.191 P3] Cierre de sesión FORZADO desde el heartbeat: el backend
        // (registrar_presencia → debeCerrar) avisa que la sesión fue cerrada (cron
        // 11pm / otro equipo / día nuevo) → limpiar TODO y volver al wizard Paso 1.
        // Money-safe: si hay un cobro/cámara en curso NO interrumpe — el próximo
        // pulso (30s) reintenta. Mismo patrón/llaves que el cierre en cascada de
        // extensiones (fix #4), que ya está probado en producción. ──
        let _meCierreForzadoPend = false;
        const _meCerrarSesionForzada = (motivo) => {
            try {
                if (_meCierreForzadoPend) return;
                if (modalPago.value || camaraAbierta.value) return;   // money-safe: reintenta en el próximo pulso
                _meCierreForzadoPend = true;
                try { _wizDetenerHeartbeat(); } catch(_){}
                try { _wizSalirPresencia(); } catch(_){}
                // [review #4] mosexpress_caja_activa NO se borra en un equipo PRINCIPAL:
                // el boot la resuelve con dinero a salvo (caja de ayer → cierre server-side
                // con arqueo real; caja de hoy → _verificarCajaServidor decide). Solo una
                // EXTENSIÓN la borra (su "caja" es un espejo de la del principal).
                const _esExt = (() => { try { return !!(config.value && config.value.esExtension) || !!JSON.parse(localStorage.getItem('mosexpress_es_extension') || 'null'); } catch(e) { return !!(config.value && config.value.esExtension); } })();
                ['mosexpress_es_extension','mosexpress_config','mosexpress_session_date','mosexpress_session_dia',
                 'mosexpress_caja_payload','mosexpress_session_start','mosexpress_ventas_hoy','mosexpress_extras_sesion',
                 'mosexpress_cobrados_sesion'].forEach(function(k){ try { localStorage.removeItem(k); } catch(_){} });
                if (_esExt) { try { localStorage.removeItem('mosexpress_caja_activa'); } catch(_){} }
                try { localStorage.setItem('mosexpress_no_recovery', '1'); } catch(_){}
                // [review #3] invalidar TAMBIÉN los snapshots de recuperación (remoto + IDB):
                // sin esto, cada reload posterior del mismo día los restauraba y el equipo
                // entraba en ping-pong "sesión recuperada"/"turno cerrado". fechaSesion=''
                // hace que el guard de recovery (fechaSesion===hoy) nunca restaure esto.
                try { _idbCat.del('session_snapshot_v1'); } catch(_){}
                try {
                    (async () => {
                        const did = localStorage.getItem('mosexpress_deviceId') || '';
                        const tk = await _mintTokenSB(); if (!did || !tk) return;
                        fetch(`${SUPABASE_URL}/rest/v1/rpc/set_device_state`, {
                            method: 'POST', keepalive: true,   // sobrevive el reload
                            headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + tk, 'Content-Profile': 'mos', 'Content-Type': 'application/json' },
                            body: JSON.stringify({ p: { deviceId: did, app: 'ME', config: { completado: false }, cajaActiva: null, fechaSesion: '' } })
                        }).catch(() => {});
                    })();
                } catch(_){}
                try { agregarToast('🌙 Turno cerrado', motivo === 'cambio-dia'
                    ? 'Empezó un nuevo día — iniciá sesión de nuevo.'
                    : 'La sesión fue cerrada (cierre de las 11pm o desde otro equipo).', 'info', 4000); } catch(_){}
                setTimeout(() => location.reload(), 1600);
            } catch(e) { _meCierreForzadoPend = false; }
        };
        // ── [v2.8.9] Pulso de presencia (heartbeat). Lo llama iniciarTurno al
        // entrar (esLogin=true) y cada ~30s mientras el turno esté activo. ──
        // [review #1] esLogin es PEGAJOSO hasta confirmarse: el pulso de login es el
        // único que reabre/crea la fila del día en el backend — si ese fetch se pierde
        // (red móvil, mint fallido), el siguiente pulso del interval REINTENTA como
        // login en vez de recibir un debeCerrar injusto a los 30s de loguearse.
        let _wizLoginPendiente = false;
        let _wizAutocuraIntentada = false;   // [2.8.345] one-shot: reintento como login ante SIN_FILA_DIA con caja abierta
        const _wizRegistrarPresencia = async (esLogin) => {
            if (offlineMode.value || API_URL === 'ENLACE_DE_TU_SCRIPT_GAS_AQUI') return;
            const cw = config.value;
            if (!cw || !cw.completado || !cw.zona) return;
            if (esLogin === true) _wizLoginPendiente = true;
            const _login = _wizLoginPendiente;
            // [v2.8.191 P3] guard de día VIVO (en TZ Perú): pestaña que cruza la
            // medianoche o PC que despierta al día siguiente → cerrar localmente,
            // NO pulsar (el pulso zombi era lo que re-creaba la fila del día nuevo).
            if (!_login && !_meSesionEsDeHoy()) {
                _meCerrarSesionForzada('cambio-dia');
                return;
            }
            // id_personal es obligatorio para el pulso; si no lo tenemos, usar el
            // nombre normalizado como identidad estable (la RPC dedupea por esta key).
            const idp = String(cw.idPersonal || '').trim() || ('NOID:' + String(cw.vendedor || '').trim().toLowerCase());
            // [v2.8.10] Base de mensajería: adjuntar device_id (siempre que exista) y
            // push_token FCM (cuando _pushInit ya lo capturó). Si el token aún no está
            // listo, se manda lo que haya (device_id) y el token en un pulso posterior;
            // la RPC conserva el previo cuando el pulso viene sin token (no lo borra).
            const _devId = (typeof deviceId !== 'undefined' && deviceId?.value) || (localStorage.getItem('mosexpress_deviceId') || '');
            const _pushTk = _pushTokenActual || '';
            try {
                const token = await _mintTokenSB();
                // [review #8i] con timeout (8s): sin él, en red colgada se apilaban
                // pulsos en vuelo y un debeCerrar stale podía llegar tardísimo.
                const _r = await _meFetchTimeout(`${SUPABASE_URL}/rest/v1/rpc/registrar_presencia`, {
                    method: 'POST',
                    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + token, 'Content-Profile': 'me', 'Content-Type': 'application/json' },
                    body: JSON.stringify({ p: {
                        id_personal: idp,
                        nombre:   cw.vendedor || '',
                        zona:     cw.zona || '',
                        estacion: cw.estacion?.Estacion_Nombre || '',
                        rol:      cw.esCajero ? 'cajero' : 'vendedor',
                        device_id:  String(_devId || ''),
                        push_token: String(_pushTk || ''),
                        // [v2.8.191 P2/P3] marcadores del cierre efectivo (SQL 415):
                        // esLogin='1' desde el wizard/retoma (reabre/crea la fila del
                        // día) y pegajoso hasta confirmar; sesionVigente marca "cliente
                        // nuevo". Un backend viejo los ignora sin daño.
                        esLogin:       _login ? '1' : '',
                        sesionVigente: '1'
                    }})
                }, 8000);
                const _j = await _r.json().catch(() => null);
                // login confirmado por el server → dejar de insistir con esLogin.
                // [2.8.345 · incidente 01-sep] SQL 1006 devuelve hookOk: si el hook de accesos falló en silencio
                // (hookOk=false) la fila del día NO existe → seguir insistiendo como login en el próximo pulso.
                // Backend viejo (sin hookOk) → comportamiento anterior.
                if (_login && _r.ok && _j && _j.ok === true && _j.hookOk !== false) _wizLoginPendiente = false;
                if (_login && _j && _j.hookOk === false) console.warn('[presencia] login sin fila del día (hook):', _j.hookError || '');
                // [v2.8.191 P3] el backend ordena cerrar (11pm / otro equipo / día
                // nuevo) → cerrar acá mismo. Backend viejo: sin debeCerrar → no-op.
                if (_j && _j.debeCerrar === true) {
                    // [2.8.345 · incidente 01-sep] AUTOCURA local: SIN_FILA_DIA con una caja REAL abierta en este
                    // equipo (cajero) = la fila del día se perdió/no se creó, NO una sesión cerrada. Reintentar UNA
                    // vez como login (recrea la fila) antes de tirar la sesión. Si vuelve a ordenar cerrar → cerrar.
                    const _cajaReal = !!cajaAbierta.value && !!idCajaActual.value && !String(idCajaActual.value).startsWith('CAJA-LOCAL-');
                    if (_j.motivo === 'SIN_FILA_DIA' && cw.esCajero && _cajaReal && !_wizAutocuraIntentada) {
                        _wizAutocuraIntentada = true;
                        _wizLoginPendiente = true;
                        console.warn('[presencia] SIN_FILA_DIA con caja abierta → reintento como login (autocura)');
                        setTimeout(() => { try { _wizRegistrarPresencia(true); } catch(_){} }, 1500);
                        return;
                    }
                    _meCerrarSesionForzada('backend');
                }
            } catch (e) { /* fire-and-forget: si fue login, _wizLoginPendiente reintenta */ }
        };
        // [fix #3 · extras unificados] Cargar TODOS los extras de la CAJA desde el backend (me.movimientos_extra_caja,
        // SQL 403) → el principal y la extensión ven los MISMOS extras. Antes cada equipo mostraba solo su
        // localStorage local (por eso el cierre sumaba bien —lee el backend— pero la vista no coincidía). Cero-GAS.
        let _extrasPollTimer = null;
        const _cargarExtrasCaja = async () => {
            try {
                const idc = idCajaActual.value;
                if (!idc || String(idc).startsWith('CAJA-LOCAL-') || offlineMode.value) return;
                const tk = await _mintTokenSB(); if (!tk) return;
                const r = await _meFetchTimeout(`${SUPABASE_URL}/rest/v1/rpc/movimientos_extra_caja`, {
                    method: 'POST',
                    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + tk, 'Content-Profile': 'me', 'Content-Type': 'application/json' },
                    body: JSON.stringify({ p: { idCaja: idc } })
                }, 8000);
                const j = await r.json().catch(() => null);
                if (!j || j.ok !== true || !Array.isArray(j.data)) return;
                extrasMovimientos.value = j.data.map(e => ({
                    id: e.id, tipo: e.tipo, monto: parseFloat(e.monto) || 0, concepto: e.concepto || '',
                    obs: e.obs || '', timestamp: e.timestamp || 0, registradoPor: e.registradoPor || '', dispositivoId: e.dispositivoId || ''
                }));
                try { lsSet('mosexpress_extras_sesion', JSON.stringify(extrasMovimientos.value)); } catch(_){}
            } catch (e) { /* fail-safe: se queda con lo local */ }
        };
        const _wizIniciarHeartbeat = (esLogin) => {
            _wizRegistrarPresencia(esLogin === true);   // [v2.8.191] true SOLO desde el wizard (login explícito)
            try { _extIniciar(); } catch (e) {}   // [companion] ¿2º device? + poll principal
            if (_wizHeartbeatTimer) clearInterval(_wizHeartbeatTimer);
            // 30s (antes 60s): mantiene al cajero "vivo" bajo la ventana de recencia de 90s de la RPC
            // presencia_por_zona → nada de coronas fantasma y desaparición rápida al irse.
            _wizHeartbeatTimer = setInterval(_wizRegistrarPresencia, 30000);
            // [fix #3] extras de la caja en vivo desde el backend (ambos equipos) + poll cada 12s.
            try { _cargarExtrasCaja(); } catch (e) {}
            if (_extrasPollTimer) clearInterval(_extrasPollTimer);
            _extrasPollTimer = setInterval(() => { try { if (document.visibilityState === 'visible') _cargarExtrasCaja(); } catch (e) {} }, 12000);
        };
        const _wizDetenerHeartbeat = () => {
            if (_wizHeartbeatTimer) { clearInterval(_wizHeartbeatTimer); _wizHeartbeatTimer = null; }
            if (_extrasPollTimer) { clearInterval(_extrasPollTimer); _extrasPollTimer = null; }
            try { _extDetener(); } catch (e) {}   // [companion]
        };
        // ── [v2.8.12] Baja EXPLÍCITA de presencia (cerrar sesión / cerrar caja). ──
        // Borra la fila de me.presencia AL INSTANTE (RPC me.salir_presencia) para que
        // el vendedor desaparezca YA del login de los demás dispositivos, sin esperar
        // el TTL de 2 min. fire-and-forget: si falla la red, el TTL lo barre igual.
        // Se le pasa el id_personal (o NOID:nombre, igual que el heartbeat) Y el
        // device_id, para limpiar también filas huérfanas del mismo aparato.
        const _wizSalirPresencia = async (idOverride, nombreOverride) => {
            if (offlineMode.value || API_URL === 'ENLACE_DE_TU_SCRIPT_GAS_AQUI') return;
            // Identidad: misma key que _wizRegistrarPresencia (id_personal o NOID:nombre).
            const cw = config.value || {};
            const _nombre = String(nombreOverride != null ? nombreOverride : (cw.vendedor || '')).trim();
            const _idRaw  = String(idOverride != null ? idOverride : (cw.idPersonal || '')).trim();
            const idp = _idRaw || (_nombre ? ('NOID:' + _nombre.toLowerCase()) : '');
            const _devId = (typeof deviceId !== 'undefined' && deviceId?.value) || (localStorage.getItem('mosexpress_deviceId') || '');
            if (!idp && !_devId) return;       // nada que dar de baja
            try {
                const token = await _mintTokenSB();
                await fetch(`${SUPABASE_URL}/rest/v1/rpc/salir_presencia`, {
                    method: 'POST',
                    keepalive: true,   // [fix rezago] el request SOBREVIVE el unload/navegación (logout) → la baja
                                       // se registra YA y el vendedor desaparece al instante para los demás.
                    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + token, 'Content-Profile': 'me', 'Content-Type': 'application/json' },
                    body: JSON.stringify({ p: { id_personal: idp, device_id: String(_devId || '') } })
                });
            } catch (e) { /* fire-and-forget: el TTL de 2min limpia igual */ }
        };

        // [fix rezago] Cierre de la app/pestaña (sin logout explícito): dar de baja la presencia al
        // unload REAL. `!e.persisted` excluye el bfcache/background de móvil (ahí el vendedor sigue
        // presente). keepalive dentro de _wizSalirPresencia asegura que el request complete.
        try {
            window.addEventListener('pagehide', (e) => {
                try {
                    if (!e.persisted && config.value && config.value.completado && config.value.vendedor) _wizSalirPresencia();
                } catch(_){}
            });
        } catch(_){}

        // ══════════════════════════════════════════════════════════════════
        // [EXTENSIÓN DE DISPOSITIVO / companion] 100% Supabase (mos.*), cero-GAS.
        // Overlays vanilla (no tocan Vue). Fail-safe: cualquier error se traga → el POS sigue.
        // ══════════════════════════════════════════════════════════════════
        let _extPollReq = null, _extPollPpal = null, _extShownAppr = {}, _extApprCooldown = {}, _extPedirAbierto = false, _extApprAbierto = false;
