                // y que el 2º equipo lo escanee ES la verificación (hay que tener ambos equipos a la mano).
                const ov = _extOverlay(`
                    <div style="text-align:center">
                        <div style="font-size:34px">📲</div>
                        <div style="font-weight:800;color:#e2e8f0;font-size:16px;margin-top:6px">Un 2º equipo quiere conectarse</div>
                        <div style="color:#38bdf8;font-weight:800;font-size:18px">${_extEsc(req.nombre || 'este usuario')}</div>
                        <div style="color:#94a3b8;font-size:12px;margin-top:6px">Mostrá el QR para que tu otro equipo lo escanee y quede vinculado.</div>
                        <div style="display:flex;gap:10px;margin-top:14px">
                            <button class="_extBtn _extBtnNo" id="_extRej">Ahora no</button>
                            <button class="_extBtn _extBtnOk" id="_extOk">📲 Mostrar QR</button>
                        </div>
                    </div>`);
