                const cerrar = () => { if (cerrado) return; cerrado = true; _extApprAbierto = false; delete _extShownAppr[req.idReq]; if (_extOverlayPplCerrar === cerrar) _extOverlayPplCerrar = null; if (autoT) clearTimeout(autoT); try { ov.remove(); } catch (e) {} };
                _extOverlayPplCerrar = cerrar;   // [100x A2] _extDetener puede cerrarlo
