    // [v2.5.22] Error handler global: si un template/computed tira excepción
    // (ej. accediendo a campo undefined en un nuevo cobro asignado), Vue
    // antes podía dejar parte del árbol unmounted → pantalla blanca. Ahora
    // capturamos, logueamos y avisamos al user con toast en vez de crashear.
    app.config.errorHandler = (err, instance, info) => {
      try { console.error('[Vue error]', info, err); } catch(_){}
      try {
        const errMsg = String((err && err.message) || err || 'error desconocido').substring(0, 120);
        // [rev200 FIX] toastContainer no existía en el DOM → el catcher de errores UI era invisible.
        let cont = document.getElementById('toastContainer');
        if (!cont) {
          cont = document.createElement('div');
          cont.id = 'toastContainer';
          cont.style.cssText = 'position:fixed;left:12px;bottom:12px;z-index:99997;display:flex;flex-direction:column;pointer-events:none';
          document.body.appendChild(cont);
        }
        if (cont) {
          const t = document.createElement('div');
          t.style.cssText = 'background:#7f1d1d;color:#fecaca;border:2px solid #dc2626;padding:10px 14px;border-radius:10px;font-size:12px;font-weight:700;max-width:340px;margin-bottom:8px;box-shadow:0 8px 24px rgba(0,0,0,.5)';
          t.innerHTML = '⚠ Error UI capturado: ' + errMsg + '<br><span style="font-size:10px;opacity:.85">(' + (info || 'sin info') + ') · App sigue operativa</span>';
          cont.appendChild(t);
          setTimeout(() => { try { t.remove(); } catch(_){} }, 8000);
        }
      } catch(_){}
    };
    app.mount('#app');
  